// Parc Pilot — helpers JS partagés

// Multi-société : si l'utilisateur connecté est un CLIENT (non super-admin), on le verrouille sur
// SA société AVANT tout (clé de cache, filtres, étiquetage des saisies). On lit le profil mis en
// cache au précédent chargement (le serveur le rafraîchit ensuite via supabase-client.js).
(function lockTenant(){
  try {
    const p = JSON.parse(localStorage.getItem('fp_profile') || 'null');
    // is_admin !== true (et pas seulement === false) : un profil is_admin NULL/absent = NON-CEO → verrouillé
    // sur sa société. Seul le CEO confirmé (is_admin === true) reste libre de basculer de société.
    if (p && p.is_admin !== true && p.societe) localStorage.setItem('fp_societe', p.societe);
  } catch (e) {}
})();

// Affichage instantané sans "flash" de chiffres : on ré-hydrate FP_DATA avec la
// dernière copie live mise en cache (écrite après chaque chargement Supabase),
// au lieu des données figées de data.js. Supabase rafraîchit juste après.
// (app.js s'exécute après data.js et avant que les pages lisent window.FP_DATA)
// ⚠️ La clé est VERSIONNÉE (…_v3). Un ancien cache périmé d'une session précédente
// écraserait sinon le data.js (à jour) par de vieux chiffres → re-flash. En changeant
// la clé, tout cache obsolète est ignoré et on repart du data.js frais jusqu'au 1er
// chargement Supabase (qui réécrit un cache propre).
// ⚠️ Clé de cache PAR SOCIÉTÉ : sinon le cache d'une société (ex. PXP) s'afficherait sur une
// autre (ex. « essaie B »). On suffixe par la société active (lue directement en localStorage,
// car FP.activeSociete n'est pas encore défini à ce stade).
window.FP_CACHE_KEY = 'fp_data_cache_v4_' + (function(){ try { return localStorage.getItem('fp_societe') || 'PXP'; } catch (e) { return 'PXP'; } })();
(function seedFromCache() {
  try { localStorage.removeItem('fp_data_cache'); } catch (e) {} // purge l'ancienne clé (non suffixée)
  // ⚡ PERF : si le loader inline de la page a DÉJÀ peuplé FP_DATA depuis un cache société COMPLET
  //    (data.js non chargé), inutile de re-parser le cache → on sort. Cf. le <script> « data.js à la
  //    demande » de chaque page. En démarrage à froid (data.js chargé), __fpSeeded est absent → on
  //    exécute la ré-hydratation habituelle (auto-réparation par clé).
  if (window.__fpSeeded) return;
  try {
    const c = JSON.parse(localStorage.getItem(window.FP_CACHE_KEY) || 'null');
    if (c && window.FP_DATA && Array.isArray(c.amendes)) {
      // Auto-réparation : un cache VIDE ne doit JAMAIS écraser des données présentes dans data.js
      // (sinon une visite faite pendant un incident — ex. 0 amende — fige la page à 0 ensuite).
      const seed = (k) => {
        if (!Array.isArray(c[k])) return;
        const cur = window.FP_DATA[k];
        if (c[k].length === 0 && Array.isArray(cur) && cur.length > 0) return; // garde data.js
        window.FP_DATA[k] = c[k];
      };
      seed('vehicules'); seed('amendes'); seed('factures'); seed('conducteurs');
    }
  } catch (e) { /* cache illisible : on garde data.js */ }
})();

// === Densité d'affichage (compact / confortable) — réglée dans Paramètres, appliquée à TOUTES les pages ===
(function applyDensity(){ try { if ((localStorage.getItem('fp_density') || '') === 'compact') document.documentElement.classList.add('fp-compact'); } catch (e) {} })();

// EXCEPTION (demande utilisateur) : les fenêtres d'IMPORT / TÉLÉVERSEMENT ne se ferment QUE
// par la croix — pas au clic sur le fond — pour ne pas perdre une saisie en cours (ex. import
// de facture, scan d'avis, carte grise). Tout le RESTE (fiches, autres modales) se ferme au clic
// en dehors, comme ÉCHAP (cf. handler plus bas). On reconnaît une fenêtre d'import si son fond
// contient une zone de téléversement (input file) ou un élément « import »/« upload ».
// On bloque alors le clic sur le fond en phase de CAPTURE (avant tout handler de fermeture).
document.addEventListener('click', (e) => {
  const t = e.target;
  if (!t || !t.matches) return;
  if (!t.matches('.modal-backdrop, [id$="-modal"]')) return;   // uniquement le FOND d'une modale
  const estImport = (t.id && /import|upload/i.test(t.id))
    || t.querySelector('input[type="file"], [id*="import" i], [id*="upload" i]');
  if (estImport) e.stopPropagation();
}, true);

// Détecte les modales/overlays « ad-hoc » créés à la volée (position:fixed, plein écran, z-index élevé)
// SANS la classe .modal-backdrop / id -modal / -backdrop (ex. état des lieux FP.edl, visionneuse photo,
// aperçus, pickers). Sert aux gardes globaux pour que FERMER cette couche (clic dehors, ×, Échap) ne
// ferme JAMAIS la fiche/tiroir en dessous → fermeture « une étape en arrière » (règle utilisateur).
// ⚠️ Retourne les overlays du plus BAS au plus HAUT (ordre DOM = ordre d'empilement pour même z-index).
function _fpAdHocOverlays() {
  try {
    const vis = (el) => el && !el.classList.contains('hidden') && getComputedStyle(el).display !== 'none' && getComputedStyle(el).visibility !== 'hidden';
    // Exclus : les couches DÉJÀ reconnues par les sélecteurs standards + la fiche elle-même + backdrops connus.
    const excl = '.modal-backdrop, [id$="-modal"], [id$="-backdrop"], .fp-dlg-backdrop, .fp-menu, .popover, .fp-popover, .drawer, .drawer-backdrop, .fp-sidebar-backdrop';
    return Array.from(document.body.children).filter((el) => {
      if (!(el instanceof HTMLElement)) return false;
      if (el.matches(excl)) return false;
      if (!vis(el)) return false;
      const cs = getComputedStyle(el);
      if (cs.position !== 'fixed') return false;
      const z = parseInt(cs.zIndex, 10) || 0;
      const big = el.offsetWidth >= window.innerWidth * 0.5 && el.offsetHeight >= window.innerHeight * 0.5;
      return z >= 1000 && big;   // couvre l'écran + au-dessus du contenu = c'est une modale
    });
  } catch (e) { return []; }
}

// Garde GLOBAL (toutes les pages + futures) : ÉCHAP ferme TOUTE zone ouverte
// (tiroir, fenêtre modale, popover, menu déroulant, résultats de recherche).
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape' && e.keyCode !== 27) return;
  const ae = document.activeElement;
  // Cas spécial : barre de recherche -> ÉCHAP vide la recherche et ferme les résultats.
  if (ae && ae.classList && ae.classList.contains('fp-search-input')) {
    ae.value = '';
    try { ae.dispatchEvent(new Event('input', { bubbles: true })); } catch (_) {}
    const res = document.querySelector('.fp-search-results'); if (res) { res.innerHTML = ''; res.style.display = 'none'; }
    ae.blur(); e.stopPropagation(); return;
  }
  // Si on saisit dans un autre champ (édition inline…), ÉCHAP est géré par le champ lui-même
  // (annule la saisie) et NE ferme PAS la zone parente.
  if (ae && /^(INPUT|SELECT|TEXTAREA)$/.test(ae.tagName)) return;
  // ⚠️ ÉCHAP ferme UNE SEULE couche à la fois — la PLUS HAUTE — « une étape en arrière ».
  // Avant, ÉCHAP fermait TOUT d'un coup (ex. le QR par-dessus une fiche fermait aussi la fiche).
  // Ordre du plus haut au plus bas : menus/popovers → fenêtres modales (QR, etc.) → tiroir (fiche).
  // ⚠️ PAS de test offsetParent : les modales/QR sont en position:fixed → offsetParent === null même
  // ouvertes. On se base sur la classe .hidden et le display calculé (fiable pour ces couches).
  const _vis = (el) => el && !el.classList.contains('hidden') && getComputedStyle(el).display !== 'none';
  let closed = false;
  // 1) Menus / popovers (couche la plus haute)
  document.querySelectorAll('.hidden-cols-popover.open, .fp-hidden-cols-popover.open, .popover.open, .fp-popover.open, #soc-menu, #mobile-menu, [id$="-menu"], [id$="-popover"], .fp-menu').forEach(el => {
    if (!_vis(el)) return; el.classList.add('hidden'); el.classList.remove('open', 'show'); closed = true;
  });
  // ⚠️ Drapeau « une couche vient d'être fermée par cet ÉCHAP » : les handlers ÉCHAP PROPRES aux pages
  // (qui ferment la fiche/tiroir) le lisent pour NE PAS fermer la fiche en même temps → fermeture « une
  // étape à la fois » (ex. le QR par-dessus une fiche ne ferme plus la fiche derrière). stopPropagation
  // ne suffit pas ici (les autres écouteurs du même document ne sont pas bloqués).
  if (closed) { try { window.__fpEscLayerClosedAt = Date.now(); } catch (_) {} e.stopPropagation(); return; }
  // 2) Fenêtres modales par-dessus le tiroir (QR, imports, etc.) — jamais le fond du tiroir lui-même
  document.querySelectorAll('.modal-backdrop, [id$="-modal"], [id$="-backdrop"]').forEach(el => {
    if (el.classList.contains('drawer-backdrop')) return;
    if (!_vis(el)) return;
    el.classList.add('hidden'); if (el.style && el.style.display && el.style.display !== 'none') el.style.display = 'none'; el.classList.remove('open'); closed = true;
  });
  if (closed) { try { window.__fpEscLayerClosedAt = Date.now(); } catch (_) {} e.stopPropagation(); return; }
  // 2bis) Modales ad-hoc plein écran (créées à la volée sans classe .modal-backdrop : état des lieux,
  // visionneuse photo, aperçus…). On ferme la PLUS HAUTE via son affordance (× / clic sur le fond),
  // et surtout on NE laisse PAS Échap tomber sur la fiche derrière → « une étape en arrière ».
  const _adhoc = _fpAdHocOverlays();
  if (_adhoc.length) {
    const ov = _adhoc[_adhoc.length - 1];   // la plus haute
    const x = ov.querySelector('[data-edl-x],[data-close],#fp-lb-x,[aria-label="Fermer"],[aria-label="Close"]');
    try { if (x) x.click(); else if (ov.click) ov.click(); } catch (_) {}
    if (document.body.contains(ov)) { try { ov.remove(); } catch (_) {} }   // repli : jamais laisser la fiche se fermer
    try { window.__fpEscLayerClosedAt = Date.now(); } catch (_) {}
    e.stopPropagation(); return;
  }
  // 3) Tiroir / fiche (couche la plus basse) — seulement si RIEN n'était ouvert au-dessus
  document.querySelectorAll('.drawer.open, .drawer-backdrop.open').forEach(el => { el.classList.remove('open'); closed = true; });
  if (closed) e.stopPropagation();
});

// Garde GLOBAL (toutes les pages + futures) : un CLIC EN DEHORS ferme la zone ouverte
// (tiroir/fiche, fenêtre modale, menu déroulant, popover, résultats de recherche),
// EXACTEMENT comme ÉCHAP. Astuce robuste : on mémorise au mousedown les zones DÉJÀ
// ouvertes, pour ne JAMAIS refermer une zone que CE clic vient justement d'ouvrir
// (sinon le menu clignote / se rouvre).
(function () {
  const FLOAT_SEL = '.hidden-cols-popover.open, .fp-hidden-cols-popover.open, .popover.open, .fp-popover.open, .fp-menu, #soc-menu, #mobile-menu, [id$="-menu"], [id$="-popover"]';
  // PAS de test offsetParent (les modales/QR sont position:fixed → offsetParent null même ouvertes).
  const isVisible = (el) => el && !el.classList.contains('hidden')
    && getComputedStyle(el).display !== 'none';
  function openZones(downTarget) {
    const out = [];
    // downInside : le mousedown a-t-il DÉMARRÉ dans cette zone ? Évalué au mousedown, AVANT tout
    // re-render → immunisé si le clic (ex. édition inline) remplace le DOM et détache la cible.
    const push = (el, type) => { if (el && !out.some(o => o.el === el)) out.push({ el, type, downInside: !!(downTarget && el.contains(downTarget)) }); };
    document.querySelectorAll('.drawer.open').forEach(el => push(el, 'drawer'));
    document.querySelectorAll('.modal-backdrop.open, [id$="-modal"], [id$="-backdrop"]').forEach(el => {
      if (el.classList.contains('drawer-backdrop')) return; // géré avec le tiroir
      if (isVisible(el) && (el.classList.contains('open') || getComputedStyle(el).display === 'flex')) push(el, 'modal');
    });
    document.querySelectorAll(FLOAT_SEL).forEach(el => { if (isVisible(el)) push(el, 'float'); });
    // Modales ad-hoc plein écran SANS classe .modal-backdrop (état des lieux, visionneuse, pickers) :
    // on les traite comme des « modal » → fermer CETTE couche (clic dehors / ×) ne ferme plus la fiche
    // en dessous (la modale gère sa propre fermeture via son handler). Correctif « revenir sur la fiche ».
    _fpAdHocOverlays().forEach(el => push(el, 'modal'));
    document.querySelectorAll('.fp-search-results').forEach(el => {
      if (el.style.display !== 'none' && (el.innerHTML || '').trim()) push(el, 'search');
    });
    return out;
  }
  let openAtDown = [];
  document.addEventListener('mousedown', (e) => {
    // ⚠️ Pop-ups flottants ancrés au <body> (calendrier .fp-dp, menus .fp-jsmenu de FP.searchSelect /
    // FP.conducteurPicker) : ils sont HORS du .drawer dans le DOM mais en font logiquement partie.
    // Sans ça, choisir une date dans le calendrier = « clic en dehors de la fiche » → la fiche se
    // fermait (bug : « je choisis une date et ça ferme la page »). On ne mémorise donc RIEN à fermer.
    if (e.target && e.target.closest && e.target.closest('.fp-dp, .fp-jsmenu')) { openAtDown = []; return; }
    openAtDown = openZones(e.target);
  }, true);
  document.addEventListener('click', (e) => {
    if (!openAtDown.length) return;
    const snap = openAtDown; openAtDown = [];
    const t = e.target;
    snap.forEach(({ el, type, downInside }) => {
      if (type === 'drawer') {
        if (downInside || el.contains(t)) return;   // clic DANS la fiche (ou démarré dedans) : on garde
        // ⚠️ Une couche est ouverte AU-DESSUS de la fiche (fenêtre modale QR/import, menu, popover…) :
        // ce clic ferme CETTE couche-là, PAS la fiche. On ne ferme jamais la fiche tant qu'un niveau
        // supérieur est ouvert → fermeture « une étape à la fois » (le QR ne ferme plus la fiche derrière).
        if (snap.some(o => o.type === 'modal' || o.type === 'float')) return;
        if (t.closest('.modal-backdrop.open, [id$="-modal"], [id$="-backdrop"], .fp-menu, .popover, .fp-popover')) return;
        el.classList.remove('open');
        document.querySelectorAll('.drawer-backdrop').forEach(bd => bd.classList.remove('open'));
        return;
      }
      if (type === 'modal') {
        if (downInside) return;                     // sélection/édition démarrée dans le panneau : on garde
        if (t === el) { el.classList.add('hidden'); el.classList.remove('open'); if (el.style && el.style.display) el.style.display = 'none'; }
        return;                                     // clic dans le panneau : on garde
      }
      if (downInside || el.contains(t)) return;     // clic À L'INTÉRIEUR de la zone (ou démarré dedans) : on garde
      if (type === 'search') { el.innerHTML = ''; el.style.display = 'none'; return; }
      el.classList.add('hidden'); el.classList.remove('open', 'show');
    });
  }, false);
})();

const FP = {
  // Format euro — null/undefined/"" /NaN ⇒ 0 (évite d'afficher "NaN €")
  euro(n) {
    const v = Number(n);
    return new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(Number.isFinite(v) ? v : 0);
  },
  euroPrecis(n) {
    const v = Number(n);
    return new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR' }).format(Number.isFinite(v) ? v : 0);
  },
  // Format date FR
  date(iso) {
    if (!iso || iso === '—') return '—';
    const d = new Date(iso);
    if (isNaN(d)) return iso;
    return d.toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' });
  },
  // Format date numérique JJ/MM/AAAA (sans nom de mois)
  dateNum(iso) {
    if (!iso || iso === '—') return '—';
    const d = new Date(iso);
    if (isNaN(d)) return iso;
    const p = n => String(n).padStart(2, '0');
    return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${d.getFullYear()}`;
  },
  // Nombre formaté — null/undefined/"" /NaN ⇒ 0 (évite d'afficher "NaN")
  num(n) {
    const v = Number(n);
    return new Intl.NumberFormat('fr-FR').format(Number.isFinite(v) ? v : 0);
  },
  // Cherche un véhicule par id
  vehicule(id) {
    return (window.FP_DATA?.vehicules || []).find(v => v.id === id);
  },
  // Badge HTML selon statut véhicule
  statutBadge(statut) {
    const map = {
      'actif':        { cls: 'badge-ok',     label: 'Actif' },
      'entretien':    { cls: 'badge-warn',   label: 'En entretien', pulse: true },
      'à vendre':     { cls: 'badge-warn',   label: 'À vendre' },
      'vendu':        { cls: 'badge-info',   label: 'Vendu' },
      'sinistre':     { cls: 'badge-danger', label: 'Sinistre', pulse: true },
      'hors service': { cls: 'badge-danger', label: 'Hors service', pulse: true },
    };
    const m = map[statut] || { cls: 'badge-info', label: (FP.esc ? FP.esc(statut) : statut) };
    return `<span class="badge ${m.cls}">${m.pulse ? '<span class="badge-dot"></span>' : ''}${m.label}</span>`;
  },
  // Anime un nombre de 0 → valeur finale (compteur), en gardant préfixe/suffixe (€, km…).
  // Appeler APRÈS avoir posé la valeur finale dans l'élément. Idempotent (1 seule fois).
  countUp(el, durationMs) {
    if (!el || el.dataset.counted === '1') return;
    try { if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) { el.dataset.counted = '1'; return; } } catch (e) {}
    const txt = (el.textContent || '').trim();
    // On n'anime PAS les valeurs décimales (ex. « 0,09 €/km ») pour ne pas les déformer.
    if (/\d[.,]\d/.test(txt)) return;
    const m = txt.match(/^(\D*?)([\d  ]*\d)(.*)$/s);
    if (!m) return;
    const target = parseInt(m[2].replace(/[^\d]/g, ''), 10);
    if (!isFinite(target) || target <= 0) { el.dataset.counted = '1'; return; }
    el.dataset.counted = '1';
    const pre = m[1], suf = m[3], dur = durationMs || 800, t0 = performance.now();
    const step = (t) => {
      const p = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - p, 3);
      el.textContent = pre + Math.round(target * e).toLocaleString('fr-FR') + suf;
      if (p < 1) requestAnimationFrame(step); else el.textContent = txt;
    };
    requestAnimationFrame(step);
  },
  // Petite explosion de confettis (succès). Respecte prefers-reduced-motion.
  celebrate(opts) {
    opts = opts || {};
    try { if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return; } catch (e) {}
    const colors = ['#F97316', '#16a34a', '#3b82f6', '#eab308', '#ec4899', '#06b6d4'];
    const n = opts.n || 20;
    const wrap = document.createElement('div');
    wrap.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:9999;overflow:hidden';
    document.body.appendChild(wrap);
    const cx = opts.x != null ? opts.x : innerWidth / 2;
    const cy = opts.y != null ? opts.y : innerHeight * 0.3;
    for (let i = 0; i < n; i++) {
      const p = document.createElement('div');
      const sz = 6 + Math.random() * 7;
      p.style.cssText = `position:absolute;left:${cx}px;top:${cy}px;width:${sz}px;height:${sz * 0.6}px;background:${colors[i % colors.length]};border-radius:2px;opacity:1;will-change:transform,opacity;transition:transform .9s cubic-bezier(.2,.6,.3,1),opacity .9s ease`;
      wrap.appendChild(p);
      const ang = (Math.PI * 2) * (i / n) + Math.random() * 0.6;
      const dist = 70 + Math.random() * 130;
      const dx = Math.cos(ang) * dist, dy = Math.sin(ang) * dist + 130;
      requestAnimationFrame(() => { p.style.transform = `translate(${dx}px,${dy}px) rotate(${Math.random() * 600}deg)`; p.style.opacity = '0'; });
    }
    setTimeout(() => wrap.remove(), 1000);
  },
  // Anneau de progression (donut) en SVG. opts: {size, stroke, color, label, textColor, fontSize, track}
  donutHTML(pct, opts) {
    opts = opts || {};
    const size = opts.size || 88, sw = opts.stroke || 10, r = (size - sw) / 2, c = 2 * Math.PI * r;
    const p = Math.max(0, Math.min(100, Number(pct) || 0));
    const off = c * (1 - p / 100);
    const col = opts.color || '#16a34a';
    const center = (opts.label != null) ? opts.label : (Math.round(p) + '%');
    return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" style="flex:0 0 ${size}px">
      <g transform="rotate(-90 ${size / 2} ${size / 2})">
        <circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${opts.track || '#e2e8f0'}" stroke-width="${sw}"/>
        <circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${col}" stroke-width="${sw}" stroke-linecap="round" stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}" style="transition:stroke-dashoffset .8s ease"/>
      </g>
      ${center !== '' ? `<text x="${size / 2}" y="${size / 2}" text-anchor="middle" dominant-baseline="central" style="font-size:${opts.fontSize || 19}px;font-weight:800;fill:${opts.textColor || '#0f1e3d'}">${center}</text>` : ''}
    </svg>`;
  },
  // Mini-courbe (sparkline) en SVG à partir d'une série de valeurs. opts: {width,height,color}
  sparklineHTML(values, opts) {
    opts = opts || {};
    const w = opts.width || 96, h = opts.height || 28;
    const vals = (values || []).map(v => Number(v) || 0);
    if (vals.length < 2) return '';
    const max = Math.max(...vals), min = Math.min(...vals), span = (max - min) || 1;
    const x = (i) => (i / (vals.length - 1) * (w - 4) + 2);
    const y = (v) => (h - 3 - ((v - min) / span) * (h - 6));
    const pts = vals.map((v, i) => `${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');
    const col = opts.color || '#0e7490';
    const lx = x(vals.length - 1).toFixed(1), ly = y(vals[vals.length - 1]).toFixed(1);
    return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="overflow:visible">
      <polyline points="${pts}" fill="none" stroke="${col}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      <circle cx="${lx}" cy="${ly}" r="2.6" fill="${col}"/>
    </svg>`;
  },
  // Jours restants entre aujourd'hui et une date ISO
  joursRestants(iso) {
    if (!iso || iso === '—') return null;
    const d = new Date(iso);
    if (isNaN(d)) return null;
    // Référence à MINUIT (comme buildEcheances) → décompte en jours calendaires cohérent partout
    // (Alertes, fiche véhicule, Renouvellements). Évite un off-by-one selon l'heure ou un DST.
    d.setHours(0, 0, 0, 0);
    const now = new Date(); now.setHours(0, 0, 0, 0);
    const diff = Math.round((d - now) / (1000*60*60*24));
    return diff;
  },
  // Calcul TVS approximatif (Taxe sur les Véhicules de Société) — démo
  tvsAnnuelle(v) {
    const d = FP.tvsDetail(v);
    return (d.applicable && d.total != null) ? d.total : 0;
  },
};

// =====================================================================
// === TVS — taxes annuelles sur l'affectation des véhicules ===========
// =====================================================================
// Remplace l'ancienne "TVS". Deux composantes :
//   1) taxe annuelle sur les émissions de CO2 (barème WLTP, marginal €/g)
//   2) taxe annuelle sur les émissions de polluants atmosphériques (selon énergie)
// ⚠️ Barème OFFICIEL 2026 (source : entreprendre.service-public.gouv.fr/vosdroits/F22203).
// Les montants changent chaque année. Ne s'applique qu'aux véhicules de tourisme (VP).
// Vérifié : un véhicule à 100 g CO2 (WLTP) = 213 € en 2026 ; 150 g = 1 733 €.
FP.TVS_ANNEE = 2026;
// Barème WLTP 2026 : tarif marginal par g/km (cumulatif par tranches)
FP.TVS_CO2_BAREME = [
  { jusqua: 4,        taux: 0 },
  { jusqua: 45,       taux: 1 },
  { jusqua: 53,       taux: 2 },
  { jusqua: 85,       taux: 3 },
  { jusqua: 105,      taux: 4 },
  { jusqua: 125,      taux: 10 },
  { jusqua: 145,      taux: 50 },
  { jusqua: 165,      taux: 60 },
  { jusqua: Infinity, taux: 65 },
];
FP.tvsCo2 = (co2) => {
  let total = 0, prev = 0;
  for (const b of FP.TVS_CO2_BAREME) {
    if (co2 > prev) { total += (Math.min(co2, b.jusqua) - prev) * b.taux; prev = b.jusqua; }
    else break;
  }
  return Math.round(total);
};
// Taxe annuelle sur les émissions de polluants atmosphériques — barème OFFICIEL 2026
// (source : entreprendre.service-public.gouv.fr/vosdroits/F22203) :
//  - Catégorie E : électrique / hydrogène → 0 €
//  - Catégorie 1 : essence, hybride, gaz conformes Euro 5/6 (1re immat ≳ 2011) → 130 €
//  - « Les plus polluants » : tout le reste (TOUS les diesels, essence/hybride antérieurs) → 650 €
// (Passe à 160 € / 800 € en 2027.) `anneeImmat` = année de 1re mise en circulation si connue.
FP.tvsPolluant = (carburant, anneeImmat) => {
  const c = (carburant || '').toLowerCase();
  if (/lectri|hydrog/.test(c)) return 0;                 // Catégorie E
  if (/diesel|gazole|gas-?oil/.test(c)) return 650;      // diesel : jamais Crit'Air 1 → catégorie la + chère
  const y = Number(anneeImmat);
  if (Number.isFinite(y) && y > 0 && y < 2011) return 650; // essence/hybride/gaz d'avant Euro 5
  return 130;                                            // essence/hybride/gaz Euro 5/6 (ou année inconnue → flotte récente)
};
// Détail TVS d'un véhicule : { applicable, raison?, co2, polluant, total, ... }
FP.tvsDetail = (v) => {
  const cat = (v.categorie || '').toLowerCase();
  const carb = v.carburant || '';
  if (/moto/.test(cat)) return { applicable: false, raison: 'Moto — non soumise' };
  if (/utilit|engin/.test(cat)) return { applicable: false, raison: 'Utilitaire — non soumis' };
  const polluant = FP.tvsPolluant(carb, (v.dateMiseEnCirculation || v.dateImmat || '').slice(0, 4));
  if (/lectri|hydrog/i.test(carb)) return { applicable: true, elec: true, co2: 0, polluant: 0, total: 0 };
  const co2 = Number(v.co2);
  // CO₂ inconnu : la taxe "polluants atmosphériques" reste due → on compte au moins le polluant
  // (la part CO₂ reste inconnue, signalée par co2Manquant), au lieu de tout mettre à 0.
  if (!Number.isFinite(co2) || co2 <= 0) return { applicable: true, co2Manquant: true, co2: null, polluant, total: polluant };
  const co2Tax = FP.tvsCo2(co2);
  return { applicable: true, co2: co2Tax, polluant, total: co2Tax + polluant };
};

// ===== Périmètres véhicules — UNE seule définition, réutilisée partout =====
// estVendu = véhicule qui ne t'appartient plus (sorti du parc). Utilisé pour la
// FLOTTE / le parc / la TVS (une voiture "à vendre" est encore possédée → comptée).
FP.estVendu = (v) => { const s = ((v && v.statut) || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim(); return s === 'vendu' || s === 'vendue'; };
// horsFlotte = véhicule DÉFINITIVEMENT sorti (vendu, cédé, hors service, archivé, restitué).
// ⚠️ « À VENDRE » N'EN FAIT PAS PARTIE (consigne utilisateur) : un véhicule en vente est ENCORE à toi →
// il se comporte comme un véhicule NORMAL partout (alertes, échéances CT/assurance, stats, TCO, km…) ;
// la SEULE différence est son étiquette « à vendre ». Source unique utilisée par toutes les alertes.
FP.horsFlotte = (v) => ['vendu', 'vendue', 'cédé', 'cede', 'cédée', 'cedee', 'hors service', 'hors-service', 'hs', 'archive', 'archivé', 'archivée', 'restitué', 'restitue', 'restituée', 'restituee'].includes(((v && v.statut) || '').toString().toLowerCase().trim());
// ⚠️ HELPER CANONIQUE — IMMOBILISATION d'un véhicule (garage / hors service temporaire).
// UNE seule source de vérité : app_settings.vehImmobilise[vehId] = { since:'YYYY-MM-DD' } (par société,
// synchronisé sur tous les appareils via FP.settings). À utiliser PARTOUT (dashboard, alertes, fiche…)
// pour marquer / lever une immobilisation — ne jamais réécrire vehImmobilise à la main ailleurs.
FP.immobilise = {
  map() { try { const s = FP.settings.get(); return (s.vehImmobilise && typeof s.vehImmobilise === 'object') ? s.vehImmobilise : {}; } catch (e) { return {}; } },
  // ⚠️ « Immobilisé » = entrée AVEC une date `since` ET SANS `leveLe`. On ne SUPPRIME plus l'entrée pour
  // lever (une suppression de clé ne se propage pas de façon fiable — la fusion anti-perte la fait
  // « revenir ») : on pose un marqueur `leveLe` (tombstone). Un CHANGEMENT de valeur, lui, se synchronise.
  is(id) { const im = this.map()[id]; return !!(im && im.since && !im.leveLe); },
  since(id) { const im = this.map()[id]; return (im && im.since && !im.leveLe) ? im.since : null; },
  jours(id) { const d = this.since(id); if (!d) return 0; const t0 = new Date(); t0.setHours(0, 0, 0, 0); return Math.max(0, Math.floor((t0 - new Date(d)) / 86400000)); },
  // on=true → marque immobilisé (depuis aujourd'hui) ; on=false → lève l'immobilisation. Persisté (Supabase).
  set(id, on) {
    try {
      const s = FP.settings.get(); s.vehImmobilise = (s.vehImmobilise && typeof s.vehImmobilise === 'object') ? s.vehImmobilise : {};
      const cur = s.vehImmobilise[id];
      if (on) { if (!cur || !cur.since || cur.leveLe) s.vehImmobilise[id] = { since: new Date().toISOString().slice(0, 10) }; }   // (ré)immobilise : nouvelle date, sans leveLe
      else { if (cur && cur.since) s.vehImmobilise[id] = { since: cur.since, leveLe: new Date().toISOString().slice(0, 10) }; else delete s.vehImmobilise[id]; }   // lève = marqueur (ne revient plus)
      return FP.settings.save(s);
    } catch (e) { return Promise.resolve(); }
  },
};
// ⚠️ HELPER CANONIQUE — montant RÉELLEMENT DÛ d'une amende : le majoré si elle est majorée,
// sinon le montant initial. À UTILISER PARTOUT (sommes, podiums, KPI, alertes, exports) pour
// que tous les écrans affichent le même montant (règle « une seule source de vérité », CLAUDE.md).
// Montant qui fait foi pour TOUS les totaux/KPI (source unique — cf. règle « une seule source de vérité ») :
//  1) si l'amende est PAYÉE et qu'un montant réellement payé a été saisi (remise/arrangement) → ce montant ;
//  2) sinon, le majoré si l'amende est majorée ;
//  3) sinon, le montant normal (minoré/forfaitaire).
// Le montant payé est stocké dans les réglages PAR SOCIÉTÉ (app_settings.amendeMontantPaye), pas en base
// (aucune colonne DB à créer). On ne lit les réglages que pour les amendes payées (pas dans toutes les boucles).
FP.montantDu = (a) => {
  if (!a) return 0;
  if (FP.estPayee(a) && a.id != null && FP.settings) {
    try {
      const ov = FP.settings.get().amendeMontantPaye;
      if (ov && ov[a.id] != null && ov[a.id] !== '') return Number(ov[a.id]) || 0;
    } catch (e) {}
  }
  return (a.majoree && a.montantMajore != null && a.montantMajore !== '') ? Number(a.montantMajore) : (Number(a.montant) || 0);
};
// ⚠️ HELPER CANONIQUE — l'amende est-elle un FPS (Forfait Post-Stationnement) plutôt qu'un avis de
// contravention ANTAI ? À UTILISER PARTOUT (règle « une seule source ») pour choisir le BON site de
// paiement et le BON délai : FPS → stationnement.gouv.fr (RAPO ~3 mois, PAS de désignation ANTAI) ;
// contravention → amendes.gouv.fr (minoré ~45 j, désignation ANTAI possible).
// ⚠️ « Stationnement » seul ne suffit PAS : un « stationnement gênant/interdit » est une CONTRAVENTION,
// pas un FPS. On tranche : (1) mention explicite FPS/forfait post-stationnement → FPS ; sinon
// (2) présence d'un n° de télépaiement ANTAI → contravention ; sinon (3) « stationnement (payant) »
// sans mention gênant/interdit → FPS.
FP.estFps = (a) => {
  if (!a) return false;
  const m = (a.motif || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  if (/forfait\s*post.?stationnement/.test(m) || /\bf\.?p\.?s\.?\b/.test(m)) return true;
  const tel = (a.numeroTelepaiement || '').toString().replace(/\D/g, '');
  // Un n° de télépaiement ANTAI (contravention) fait 14 à 18 chiffres (souvent 14, débute par 333).
  // ⚠️ Un FPS a AUSSI un long numéro (« n° de l'avis de paiement » = préfixe 14 + groupe 12 = 26 ch.) :
  // il ne faut PAS le prendre pour un télépaiement ANTAI → on ne conclut « contravention » QUE dans la
  // plage 10-18 (au-delà de 18 = c'est le numéro d'avis de paiement d'un FPS, pas un télépaiement ANTAI).
  if (tel.length >= 10 && tel.length <= 18) return false; // n° de télépaiement ANTAI présent ⇒ contravention amendes.gouv.fr
  if (/stationnement/.test(m) && !/(genant|interdit|dangereux|abusif|arret|double|trottoir|passage|livraison|bande|couloir|\bbus\b)/.test(m)) return true;
  return false;
};
// Enregistre (ou efface si val vide) le montant réellement payé d'une amende — réglages par société, partagé entre postes.
FP.setAmendeMontantPaye = (id, val) => {
  if (!FP.settings || id == null) return;
  const s = FP.settings.get();
  const map = (s.amendeMontantPaye && typeof s.amendeMontantPaye === 'object') ? s.amendeMontantPaye : {};
  if (val == null || val === '' || isNaN(Number(val))) delete map[id];
  else map[id] = Number(val);
  s.amendeMontantPaye = map;
  FP.settings.save(s);
};
FP.getAmendeMontantPaye = (id) => {
  try { const m = FP.settings.get().amendeMontantPaye; return (m && m[id] != null && m[id] !== '') ? Number(m[id]) : null; } catch (e) { return null; }
};
// Détail des 3 montants officiels d'un avis (minoré / forfaitaire / majoré) + les 2 dates limites,
// lus par l'IA au scan. Stockés PAR SOCIÉTÉ dans les réglages (app_settings.amendeMontants[id]) —
// AUCUNE colonne DB à créer. On ne change PAS le montant qui fait foi (FP.montantDu) : c'est juste
// pour ne pas PERDRE la ventilation lue et pouvoir l'afficher / l'exploiter plus tard.
FP.setAmendeMontants = (id, o) => {
  if (!FP.settings || id == null) return;
  const s = FP.settings.get();
  const map = (s.amendeMontants && typeof s.amendeMontants === 'object') ? s.amendeMontants : {};
  const clean = {};
  ['montantMinore', 'montantForfaitaire', 'montantMajore', 'dateLimiteMinore', 'dateLimiteForfaitaire'].forEach(k => {
    const v = o && o[k]; if (v != null && v !== '') clean[k] = v;
  });
  if (Object.keys(clean).length) { map[id] = clean; s.amendeMontants = map; FP.settings.save(s); }
};
FP.getAmendeMontants = (id) => {
  try { const m = FP.settings.get().amendeMontants; return (m && m[id]) ? m[id] : null; } catch (e) { return null; }
};
// ⚠️ HELPER CANONIQUE — anomalies « À vérifier » d'une amende (incohérences typiques des amendes FR
// / avis ANTAI). Renvoie [{champ, msg}] (vide = cohérent). Lu par la FICHE amende ET l'écran de SCAN
// (même source de vérité). Volontairement TOLÉRANT : on ne signale que des incohérences NETTES
// (jamais un simple doute) pour éviter les faux positifs. `bdOverride` = ventilation des 3 tarifs
// quand l'amende n'est pas encore enregistrée (écran de scan) ; sinon on lit FP.getAmendeMontants.
FP.amendeAnomalies = (a, bdOverride) => {
  const out = []; if (!a) return out;
  const dg = v => String(v == null ? '' : v).replace(/\D/g, '');
  const nb = v => { if (v == null || v === '') return null; const n = Number(String(v).replace(',', '.').replace(/[^\d.\-]/g, '')); return isNaN(n) ? null : n; };
  const isDate = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);
  const etr = /étrang|etrang/i.test(String(a.commentaire || '')); // amende étrangère → règles FR non applicables

  // Clé de télépaiement = EXACTEMENT 2 chiffres (standard ANTAI).
  const cle = dg(a.cle);
  if (cle && cle.length !== 2) out.push({ champ: 'cle', msg: `Clé de télépaiement : ${cle.length} chiffre(s) au lieu de 2.` });

  // N° d'avis de contravention : présent sur tout avis ANTAI (obligatoire). Absent = à compléter.
  // (Pas pour une amende étrangère, qui n'a pas de n° ANTAI.)
  const avis = dg(a.numeroAvis);
  if (!etr && !avis) out.push({ champ: 'numeroAvis', msg: "N° d'avis de contravention manquant." });

  // N° de télépaiement : officiellement 14 À 18 chiffres (souvent 14, débute par 333), + une clé de
  // 2 chiffres À PART (source : amendes.gouv.fr / ANTAI). On ne signale donc QUE hors de cette plage
  // (ex. un chiffre sauté → 13, ou un chiffre en trop → 19+) : dans la plage 14-18 c'est NORMAL, pas
  // d'alerte pour rien. Un FPS (stationnement.gouv.fr) suit un autre format → on ne contrôle pas sa longueur.
  const tp = dg(a.numeroTelepaiement);
  if (tp && !(FP.estFps ? FP.estFps(a) : false) && (tp.length < 14 || tp.length > 18)) {
    out.push({ champ: 'numeroTelepaiement', msg: `N° de télépaiement : ${tp.length} chiffres (attendu 14 à 18) — un chiffre manque ou en trop ?` });
  }

  // Points retirés : plage 0 à 6.
  const p = nb(a.points);
  if (p != null && (p < 0 || p > 6)) out.push({ champ: 'points', msg: `Points retirés hors plage 0–6 (${p}).` });

  // Montant + cohérence avec les 3 tarifs officiels lus par l'IA.
  const m = nb(a.montant);
  const bd = bdOverride || ((FP.getAmendeMontants && a.id != null) ? FP.getAmendeMontants(a.id) : null);
  const mn = bd ? nb(bd.montantMinore) : null, mf = bd ? nb(bd.montantForfaitaire) : null, mj = bd ? nb(bd.montantMajore) : null;
  const eur = v => (FP.euro ? FP.euro(v) : v + ' €');
  if (m != null) {
    if (m < 0) out.push({ champ: 'montant', msg: 'Montant négatif.' });
    else if (!etr && m > 1500) out.push({ champ: 'montant', msg: `Montant inhabituellement élevé (${eur(m)}) — à confirmer.` });
  }
  // Ordre officiel minoré < forfaitaire < majoré (quand présents).
  if (mn != null && mf != null && mn > mf) out.push({ champ: 'montant', msg: `Le minoré (${mn}) dépasse le forfaitaire (${mf}).` });
  if (mf != null && mj != null && mf > mj) out.push({ champ: 'montant', msg: `Le forfaitaire (${mf}) dépasse le majoré (${mj}).` });
  if (mn != null && mj != null && mn > mj) out.push({ champ: 'montant', msg: `Le minoré (${mn}) dépasse le majoré (${mj}).` });
  // Le montant retenu doit être l'un des 3 tarifs lus (sinon = chiffre parasite type « 1875 »).
  const trio = [mn, mf, mj].filter(v => v != null && v > 0);
  if (m != null && m > 0 && trio.length && !trio.some(v => Math.abs(v - m) < 0.5)) {
    out.push({ champ: 'montant', msg: `Le montant retenu (${m}) ne figure dans aucun des 3 tarifs lus (${trio.join(' / ')}).` });
  }

  // Dates.
  const today = new Date().toISOString().slice(0, 10);
  if (isDate(a.date) && a.date > today) out.push({ champ: 'date', msg: "Date de l'infraction dans le futur." });
  if (bd) {
    if (isDate(bd.dateLimiteMinore) && isDate(a.date) && bd.dateLimiteMinore < a.date) out.push({ champ: 'date', msg: 'Date limite (tarif minoré) antérieure à l’infraction.' });
    if (isDate(bd.dateLimiteForfaitaire) && isDate(bd.dateLimiteMinore) && bd.dateLimiteForfaitaire < bd.dateLimiteMinore) out.push({ champ: 'date', msg: 'Date limite forfaitaire antérieure à la date limite minoré.' });
  }
  return out;
};
// Rendu HTML réutilisable du bandeau « À vérifier » (fiche + scan). '' si aucune anomalie.
FP.amendeAnomaliesBanner = (a, bdOverride, opts) => {
  const anos = FP.amendeAnomalies ? FP.amendeAnomalies(a, bdOverride) : [];
  if (!anos.length) return '';
  const esc = FP.esc || (s => String(s == null ? '' : s));
  const hint = (opts && opts.hint) || 'Cliquez sur un champ ci-dessous pour corriger.';
  return `<div style="background:#FFFBEB;border:1px solid #FCD34D;border-left:4px solid #D97706;border-radius:.55rem;padding:.6rem .8rem">
    <div style="color:#B45309;font-weight:800;font-size:.85rem;display:flex;align-items:center;gap:.35rem"><span>⚠️</span> À vérifier${anos.length > 1 ? ' (' + anos.length + ')' : ''}</div>
    <ul style="margin:.3rem 0 0;padding-left:1.1rem;color:#92400E;font-size:.75rem;line-height:1.5">${anos.map(x => '<li>' + esc(x.msg) + '</li>').join('')}</ul>
    <div style="color:#B45309;opacity:.65;font-size:.68rem;margin-top:.25rem">${esc(hint)}</div>
  </div>`;
};
// ⚠️ HELPER CANONIQUE — année d'une amende (peut revenir en NOMBRE depuis Supabase) : on force
// en chaîne, avec repli sur l'année de la date. Évite les filtres `annee === '2026'` qui ratent le nombre.
FP.anneeAmende = (a) => { if (!a) return ''; const y = a.annee; if (y != null && String(y).trim() !== '') return String(y).trim(); return String(a.date || '').slice(0, 4); };
// ⚠️ HELPER CANONIQUE — coût d'EXPLOITATION d'un mois (AAAA-MM) : somme des factures TTC en
// EXCLUANT leasing / sinistre / achat de véhicule / cession (investissement ou argent entrant,
// pas une charge d'exploitation). À utiliser PARTOUT (dashboard, écran mural, rapport direction)
// pour que « Coût du mois » affiche le même chiffre. `exclureType` réutilisable seul.
FP.coutFactureExploit = (f) => { const t = String((f && f.type) || '').toLowerCase(); return t !== 'leasing' && t !== 'sinistre' && t !== 'achat' && t !== 'cession'; };
// ⚠️ INSERTION FACTURE TOLÉRANTE aux colonnes optionnelles (source/categorie/conducteur) — celles-ci
// n'existent qu'après la migration `supabase/factures-notes-de-frais-columns.sql`. Si la base refuse
// une colonne inconnue (schema cache / column does not exist), on RÉESSAIE sans ces colonnes → la
// facture est TOUJOURS enregistrée (elle compte dans le TCO ; le discriminateur vit dans `type` /
// `fournisseur` qui existent toujours). Les métadonnées se rempliront une fois la migration passée.
// À utiliser pour tout ajout de facture porteuse de source/categorie/conducteur (notes de frais, Sanef).
FP.FACTURE_OPT_COLS = ['source', 'categorie', 'conducteur'];
FP.persistFacture = async (rec) => {
  if (!(FP.db && FP.db.insert && FP.supabase)) { try { FP.persist.insert('factures', rec); } catch (e) {} return; }
  try {
    const r = await FP.db.insert('factures', rec);
    if (r && r.error) throw r.error;
    if (FP.refreshDataCache) FP.refreshDataCache();
  } catch (e) {
    const msg = String((e && (e.message || e.details || e.code)) || '').toLowerCase();
    const hasOpt = FP.FACTURE_OPT_COLS.some(k => rec[k] != null);
    if (hasOpt && /(column|schema cache|could not find|does not exist|pgrst)/.test(msg)) {
      const core = Object.assign({}, rec); FP.FACTURE_OPT_COLS.forEach(k => delete core[k]);
      try { const r2 = await FP.db.insert('factures', core); if (r2 && r2.error) throw r2.error; if (FP.refreshDataCache) FP.refreshDataCache(); }
      catch (e2) { try { FP.persist.insert('factures', core); } catch (_) {} }
      if (!FP._factureOptWarned) { FP._factureOptWarned = true; console.warn('[factures] colonnes source/categorie/conducteur absentes — exécuter supabase/factures-notes-de-frais-columns.sql pour tout enregistrer (métadonnées + multi-appareils).'); }
    } else {
      try { FP.persist.insert('factures', rec); } catch (_) {} // erreur réseau → file d'attente (réessai auto)
    }
  }
};
// Charge SheetJS (lecture Excel .xlsx/.xls/.csv) À LA DEMANDE (comme jsPDF). Renvoie une promesse
// résolue quand window.XLSX est prêt (false si échec). Réutilisé par les imports par lot (notes de
// frais, état de parc…). Source unique → un seul chargeur pour toute la plateforme.
FP.ensureXLSX = () => {
  if (window.XLSX) return Promise.resolve(true);
  if (FP._xlsxP) return FP._xlsxP;
  FP._xlsxP = new Promise((res) => {
    const sc = document.createElement('script');
    sc.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
    sc.onload = () => res(!!window.XLSX);
    sc.onerror = () => { FP._xlsxP = null; res(false); };
    document.head.appendChild(sc);
  });
  return FP._xlsxP;
};

// ============================================================================================
// QR VÉHICULE — module PARTAGÉ (source UNIQUE). Génère EXACTEMENT la même carte QR que la fiche
// véhicule (buildCanvas + card), et permet d'exporter TOUS les QR en un PDF. Utilisé par
// vehicules.html (QR d'un véhicule) ET conducteurs.html (« Télécharger tous les QR »). Une seule
// source → PNG / impression / PDF groupé pixel-cohérents.
// ============================================================================================
FP.qr = {
  MENU_BASE: 'https://parc-pilot.fr/v.html?h=',
  _libP: null,
  ensureLib() {
    if (window.qrcode) return Promise.resolve(true);
    if (this._libP) return this._libP;
    this._libP = new Promise((res) => {
      const pfx = /\/pages\//.test(location.pathname) ? '../' : '';
      const s = document.createElement('script'); s.src = pfx + 'assets/js/vendor/qrcode.js';
      s.onload = () => res(!!window.qrcode); s.onerror = () => { this._libP = null; res(false); };
      document.head.appendChild(s);
    });
    return this._libP;
  },
  // QR brut (carré noir & blanc). `qrcode` doit être chargé (ensureLib).
  buildCanvas(url, scale, margin) {
    const qr = qrcode(0, 'M'); qr.addData(url); qr.make();
    const n = qr.getModuleCount(), s = scale || 10, m = (margin == null ? 4 : margin);
    const size = (n + m * 2) * s;
    const c = document.createElement('canvas'); c.width = c.height = size;
    const ctx = c.getContext('2d'); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, size, size); ctx.fillStyle = '#000';
    for (let r = 0; r < n; r++) for (let col = 0; col < n; col++) if (qr.isDark(r, col)) ctx.fillRect((col + m) * s, (r + m) * s, s, s);
    return c;
  },
  _roundRect(ctx, x, y, w, h, r) {
    if (ctx.roundRect) { ctx.beginPath(); ctx.roundRect(x, y, w, h, r); return; }
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
  },
  _wrap(ctx, text, maxW) {
    const words = String(text || '').split(' '); const lines = []; let line = '';
    for (let i = 0; i < words.length; i++) { const t = line ? line + ' ' + words[i] : words[i]; if (ctx.measureText(t).width > maxW && line) { lines.push(line); line = words[i]; } else line = t; }
    if (line) lines.push(line); return lines;
  },
  // Carte QR de marque (logo société + plaque + modèle + QR + astuce). `qrData` = {immat,label,url,hint}.
  // Appelle cb(canvas). MÊME rendu que la fiche véhicule (copie fidèle de renderQrCard).
  card(qrData, cb) {
    if (!qrData || !qrData.url) { cb(null); return; }
    let logo = ''; try { const _p = FP.settings.get().profil || {}; logo = _p.logoDataUrl || _p.logoUrl || ''; } catch (e) {}
    const titre = (qrData.immat || '');
    const modele = (qrData.label || '').replace(qrData.immat || '', '').replace(/^[\s·•-]+/, '').trim();
    const hint = qrData.hint || 'Scannez pour ouvrir la fiche du véhicule';
    const qrc = this.buildCanvas(qrData.url, 12, 4);
    const draw = (logoImg) => {
      const R = 2;
      const padX = 56 * R, padTop = 46 * R, padBottom = 42 * R, gap = 16 * R;
      const socSize = 30 * R, modSize = 24 * R, hintSize = 21 * R;
      const qrSize = 480 * R;
      const tmp = document.createElement('canvas').getContext('2d');
      tmp.font = '800 ' + socSize + 'px Inter,Arial,sans-serif';
      const titleW = tmp.measureText(titre || '').width;
      const W = Math.max(qrSize + padX * 2, Math.ceil(titleW) + padX * 2);
      let logoH = 0, logoW = 0;
      if (logoImg && logoImg.naturalWidth) {
        const maxH = 200 * R, maxW = Math.min(420 * R, W - padX * 2);
        const sc = Math.min(maxH / logoImg.naturalHeight, maxW / logoImg.naturalWidth);
        logoH = logoImg.naturalHeight * sc; logoW = logoImg.naturalWidth * sc;
      }
      tmp.font = '500 ' + hintSize + 'px Inter,Arial,sans-serif';
      const hintLines = this._wrap(tmp, hint, W - padX * 2);
      let H = padTop;
      if (logoH) H += logoH + Math.round(gap * 2.3);
      H += socSize + Math.round(modele ? gap * 0.55 : gap * 1.6);
      if (modele) H += modSize + Math.round(gap * 0.6);
      H += qrSize + Math.round(gap * 1.3);
      H += hintLines.length * Math.round(hintSize * 1.3) + padBottom;
      const c = document.createElement('canvas'); c.width = W; c.height = H;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, W, H);
      ctx.strokeStyle = '#0f1e3d'; ctx.lineWidth = 3 * R;
      this._roundRect(ctx, 6 * R, 6 * R, W - 12 * R, H - 12 * R, 18 * R); ctx.stroke();
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      let cy = padTop;
      if (logoH) { ctx.drawImage(logoImg, (W - logoW) / 2, cy, logoW, logoH); cy += logoH + Math.round(gap * 2.3); }
      ctx.fillStyle = '#0f1e3d'; ctx.font = '800 ' + socSize + 'px Inter,Arial,sans-serif';
      ctx.fillText(titre, W / 2, cy); cy += socSize + Math.round(modele ? gap * 0.55 : gap * 1.6);
      if (modele) { ctx.fillStyle = '#64748b'; ctx.font = '600 ' + modSize + 'px Inter,Arial,sans-serif'; ctx.fillText(modele, W / 2, cy); cy += modSize + Math.round(gap * 0.6); }
      ctx.drawImage(qrc, (W - qrSize) / 2, cy, qrSize, qrSize); cy += qrSize + Math.round(gap * 1.3);
      ctx.fillStyle = '#94a3b8'; ctx.font = '500 ' + hintSize + 'px Inter,Arial,sans-serif';
      const lh = Math.round(hintSize * 1.3);
      hintLines.forEach((ln, i) => ctx.fillText(ln, W / 2, cy + i * lh));
      cb(c);
    };
    const _startDraw = (src) => { if (!src) { draw(null); return; } const im = new Image(); im.onload = () => draw(im); im.onerror = () => draw(null); im.src = src; };
    if (logo && !/^data:/i.test(logo)) {
      fetch(logo, { mode: 'cors' }).then(r => r.blob()).then(b => { const fr = new FileReader(); fr.onload = () => _startDraw(fr.result); fr.onerror = () => _startDraw(null); fr.readAsDataURL(b); }).catch(() => _startDraw(null));
    } else { _startDraw(logo); }
  },
  // Récupère les données QR d'un véhicule (jeton permanent km_qr). Renvoie {immat,label,url,hint} ou null.
  async dataFor(v) {
    if (!(window.FP && FP.kmCollecte && FP.kmCollecte.ensureQr)) return null;
    const r = await FP.kmCollecte.ensureQr(v);
    if (!r || !r.ok) return null;
    const token = (FP.kmCollecte._qrByVeh && FP.kmCollecte._qrByVeh[v.id]) || '';
    if (!token) return null;
    const immat = v.immat || '';
    return { immat, label: `${immat} · ${v.marque || ''} ${v.modele || ''}`.trim(), url: this.MENU_BASE + encodeURIComponent(token), hint: 'Scannez : véhicule · km · documents · sinistre · état des lieux' };
  },
  // Exporte TOUS les QR (un par page A4) dans un seul PDF — MÊME carte que l'impression/PNG unitaire.
  async downloadAllPdf(vehs, opts) {
    opts = opts || {};
    const okLib = await this.ensureLib();
    if (!okLib) { alert('Librairie QR indisponible (connexion requise).'); return; }
    if (!(window.jspdf && window.jspdf.jsPDF)) { if (FP.ensureJsPDF) { await FP.ensureJsPDF(); } }
    if (!(window.jspdf && window.jspdf.jsPDF)) { alert('Générateur PDF indisponible.'); return; }
    // On exporte EXACTEMENT la liste fournie par l'appelant (déjà filtrée côté page) → ne pas
    // re-filtrer ici sur horsFlotte, sinon les « à vendre » / restitués / HS étaient exclus à tort
    // (l'utilisateur veut le QR de TOUTE la flotte affichée, pas seulement les véhicules « actifs »).
    const list = (vehs || []).filter(v => v && v.immat);
    if (!list.length) { alert('Aucun véhicule à exporter.'); return; }
    const busy = FP.busy ? FP.busy('Génération des QR… 0/' + list.length) : null;
    const doc = new window.jspdf.jsPDF({ unit: 'mm', format: 'a4' });
    const pw = doc.internal.pageSize.getWidth(), ph = doc.internal.pageSize.getHeight();
    let added = 0, fail = 0;
    for (let i = 0; i < list.length; i++) {
      if (busy) busy.update('Génération des QR… ' + (i + 1) + '/' + list.length);
      const v = list[i];
      let d = null; try { d = await this.dataFor(v); } catch (e) {}
      if (!d) { fail++; continue; }
      const canvas = await new Promise(res => { try { this.card(d, res); } catch (e) { res(null); } });
      const cnv = canvas || this.buildCanvas(d.url, 12, 4);
      const img = cnv.toDataURL('image/png');
      const ratio = cnv.height / cnv.width;
      const mW = Math.min(120, pw - 30), mH = mW * ratio;   // carte centrée, largeur ≤ 120 mm
      const finalH = Math.min(mH, ph - 30), finalW = finalH / ratio;
      if (added > 0) doc.addPage();
      doc.addImage(img, 'PNG', (pw - finalW) / 2, (ph - finalH) / 2, finalW, finalH);
      added++;
    }
    if (!added) { if (busy) busy.fail('Aucun QR généré.'); else alert('Aucun QR généré.'); return; }
    doc.save('qr-vehicules' + (opts.suffix ? '-' + opts.suffix : '') + '.pdf');
    if (busy) busy.done('✓ ' + added + ' QR exporté(s)' + (fail ? ' · ' + fail + ' échec(s)' : ''));
  }
};

// ============================================================================================
// RELEVÉ KM — module PARTAGÉ (source unique). Rend le suivi complet des relevés km dans un
// conteneur donné + câble ses interactions. Utilisé nativement par la page Contrôle (sous-onglet
// « Relevé KM »). Zéro iframe, zéro cross-page. `opts.onChange` (optionnel) = rappel après une
// modif (pour rafraîchir d'autres vues éventuelles). Dépendances : FP.kmCollecte, FP.notifCfg,
// FP.settings, FP.kmSuivi/kmSuiviSet, FP.kmActuel, FP.horsFlotte, FP.blockingRevisionFactures…
// ============================================================================================
FP.releveKm = (function () {
  const RK_STATUT = {
    ajour:    { label: 'À jour',      bg: 'rgba(21,128,61,.12)',  fg: '#15803D', dot: '#22C55E' },
    attente:  { label: 'En attente',  bg: 'rgba(180,83,9,.12)',   fg: '#B45309', dot: '#F59E0B' },
    relancer: { label: 'À relancer',  bg: 'rgba(194,65,12,.14)',  fg: '#C2410C', dot: '#FB923C' },
    jamais:   { label: 'Jamais reçu', bg: 'rgba(185,28,28,.12)',  fg: '#B91C1C', dot: '#EF4444' },
  };
  const rkChannel = (r) => (r && r.source === 'qr' ? 'QR scanné' : 'E-mail');
  const esc = (s) => (FP.esc ? FP.esc(s) : String(s == null ? '' : s));
  const D = () => window.FP_DATA || { vehicules: [] };
  let _box = null, _onChange = null;
  const changed = () => { paint(); if (_onChange) { try { _onChange(); } catch (e) {} } };

  function rkBuildRows() {
    const KC = window.FP && FP.kmCollecte;
    const cfg = (FP.notifCfg ? FP.notifCfg() : {});
    const seuil = cfg.releveKmJours || 45;
    const today = new Date();
    const vehs = (D().vehicules || []).filter(v => !(FP.horsFlotte && FP.horsFlotte(v)) && (!FP.kmSuivi || FP.kmSuivi(v)));
    return vehs.map(v => {
      const readings = (KC && KC.recusDe) ? KC.recusDe(v) : [];
      const last = readings[0] || null;                                   // dernier relevé AFFICHÉ (tout canal)
      const stt = (KC && KC.statusFor) ? KC.statusFor(v) : null;
      const pending = (stt && stt.sent_at && !stt.used_at) ? stt : null;
      const lastDate = last ? new Date(last.used_at) : null;
      const daysSince = lastDate ? Math.floor((today - lastDate) / 86400000) : null;
      // Statut = même règle que les Relances (source unique) : un scan QR ne compte que s'il suit une
      // relance mail, et « à jour » = relevé daté APRÈS le cutoff (délai + date de cycle). Le dernier
      // relevé AFFICHÉ (date + canal) reste, lui, le plus récent tout canal.
      const lastCompte = (KC && KC.recusComptesDe) ? (KC.recusComptesDe(v)[0] || null) : last;
      const cutoff = (KC && KC._cutoff) ? KC._cutoff() : (today.getTime() - seuil * 86400000);
      let statut;
      if (lastCompte && new Date(lastCompte.used_at).getTime() >= cutoff) statut = 'ajour';
      else if (pending) statut = 'attente';
      else if (readings.length) statut = 'relancer';
      else statut = 'jamais';
      const email = (KC && KC.emailDe) ? KC.emailDe(v) : '';
      return { v, readings, last, pending, lastDate, daysSince, statut, email };
    });
  }

  function paint() {
    const box = _box; if (!box) return;
    const KC = window.FP && FP.kmCollecte;
    if (KC && KC.load && KC._cache == null) { box.dataset.loading = '1'; KC.load().then(() => paint()); }
    const loading = KC && KC._cache == null;
    const cfg = (FP.notifCfg ? FP.notifCfg() : {});
    const seuil = cfg.releveKmJours || 45, relance = cfg.releveKmRelanceJours || 7;
    const canEditKm = (FP.isAdmin && FP.isAdmin()) || (FP.isGestionnaire && FP.isGestionnaire());
    const rows = rkBuildRows();
    const cnt = { ajour: 0, attente: 0, relancer: 0, jamais: 0 };
    rows.forEach(r => cnt[r.statut]++);
    const total = rows.length || 1;
    const okPct = Math.round(cnt.ajour / total * 100);
    const manquants = cnt.relancer + cnt.jamais;
    const avecMail = rows.filter(r => r.statut !== 'ajour' && r.email).length;
    const nonSuivi = (D().vehicules || []).filter(v => !(FP.horsFlotte && FP.horsFlotte(v)) && FP.kmSuivi && !FP.kmSuivi(v)).length;
    const ordre = { jamais: 0, relancer: 1, attente: 2, ajour: 3 };
    const sorted = rows.slice().sort((a, b) => (ordre[a.statut] - ordre[b.statut]) || (a.v.immat || '').localeCompare(b.v.immat || ''));
    const tile = (val, lbl, grad, accent) => `
      <div class="rk-tile" style="background:${grad}">
        <div class="rk-tile-val">${val}</div>
        <div class="rk-tile-lbl">${lbl}</div>
        <div class="rk-tile-bar" style="background:${accent}"></div>
      </div>`;
    const rowHTML = (r) => {
      const S = RK_STATUT[r.statut];
      const v = r.v;
      const km = FP.kmActuel ? FP.kmActuel(v) : (Number(v.km) || 0);
      const chauffeur = (v.chauffeur && v.chauffeur !== '—') ? esc(v.chauffeur) : '<span style="color:var(--fp-muted)">— sans chauffeur</span>';
      const lastTxt = r.lastDate
        ? `${FP.dateNum(r.last.used_at)} <span class="rk-since">(il y a ${r.daysSince} j · ${rkChannel(r.last)})</span>`
        : '<span style="color:var(--fp-muted)">jamais</span>';
      const pendTxt = r.pending ? ` · <span style="color:#B45309">demande envoyée le ${FP.dateNum(r.pending.sent_at)}</span>` : '';
      let hist = '';
      if (r.readings.length) {
        hist = r.readings.map((rd, i) => {
          const older = r.readings[i + 1];
          let delta = '';
          if (older && rd.km_recu != null && older.km_recu != null) {
            const dk = Number(rd.km_recu) - Number(older.km_recu);
            const dj = Math.max(1, Math.round((new Date(rd.used_at) - new Date(older.used_at)) / 86400000));
            delta = ` <span class="rk-delta">+${FP.num(dk)} km en ${dj} j</span>`;
          }
          return `<div class="rk-hrow"><span class="rk-hdate">${FP.dateNum(rd.used_at)}</span><b>${FP.num(rd.km_recu)} km</b>${delta}<span class="rk-hchan">${rkChannel(rd)}</span></div>`;
        }).join('');
      } else { hist = '<div class="rk-hrow" style="color:var(--fp-muted)">Aucun relevé reçu pour l\'instant.</div>'; }
      const actionBtn = (r.statut !== 'ajour' && r.email)
        ? `<button type="button" class="rk-ask" data-rk-ask="${esc(v.id)}" title="Envoyer une demande de relevé à ${esc(r.email)}"><i data-lucide="mail" class="w-3.5 h-3.5"></i> Demander</button>`
        : (r.statut !== 'ajour' ? '<span class="rk-noemail" title="Pas d\'e-mail chauffeur">✉︎ pas d\'e-mail</span>' : '');
      return `<div class="rk-item" data-rk-veh="${esc(v.id)}">
        <div class="rk-main" data-rk-toggle="${esc(v.id)}">
          <span class="rk-dot" style="background:${S.dot}"></span>
          <div class="rk-idcol">
            <a href="vehicules.html?veh=${encodeURIComponent(v.id)}" class="rk-plate" onclick="event.stopPropagation()">${esc(v.immat || '?')}</a>
            <span class="rk-model">${esc((v.marque || '') + ' ' + (v.modele || ''))}</span>
          </div>
          <div class="rk-chauf">${chauffeur}</div>
          <div class="rk-km">${FP.num(km)} km</div>
          <div class="rk-last">${lastTxt}${pendTxt}</div>
          <span class="rk-pill" style="background:${S.bg};color:${S.fg}">${S.label}</span>
          <div class="rk-actions">${actionBtn}<i data-lucide="chevron-down" class="w-4 h-4 rk-chev"></i></div>
        </div>
        <div class="rk-detail" hidden>
          <div class="rk-detail-head">Historique des relevés <span style="color:var(--fp-muted);font-weight:400">(du plus récent au plus ancien)</span></div>
          ${hist}
          ${canEditKm ? `<div class="rk-edit">
            <label for="rk-km-${esc(v.id)}">Corriger / saisir le km</label>
            <input id="rk-km-${esc(v.id)}" type="number" min="1" step="1" inputmode="numeric" placeholder="ex. ${km || 45000}" data-rk-km="${esc(v.id)}">
            <button type="button" class="rk-btn" data-rk-km-save="${esc(v.id)}"><i data-lucide="check" class="w-4 h-4"></i> Enregistrer</button>
            <span class="rk-km-st" data-rk-km-st="${esc(v.id)}"></span>
          </div>` : ''}
        </div>
      </div>`;
    };
    box.innerHTML = `
      <style>
        .rk-wrap{display:flex;flex-direction:column;gap:18px}
        .rk-tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
        @media(max-width:720px){.rk-tiles{grid-template-columns:repeat(2,1fr)}}
        .rk-tile{position:relative;border-radius:16px;padding:18px 18px 22px;color:#fff;overflow:hidden;box-shadow:0 18px 40px -22px rgba(11,18,32,.85),inset 0 1px 0 rgba(255,255,255,.08);transition:transform .15s}
        .rk-tile:hover{transform:translateY(-2px)}
        .rk-tile-val{font-size:2.1rem;font-weight:900;line-height:1;letter-spacing:-.02em}
        .rk-tile-lbl{font-size:.78rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.72);margin-top:8px}
        .rk-tile-bar{position:absolute;left:0;bottom:0;height:4px;width:100%}
        .rk-card{background:var(--fp-surface,#fff);border:1px solid var(--fp-border);border-radius:16px;padding:18px 20px;box-shadow:0 12px 30px -24px rgba(15,30,61,.5)}
        .rk-cfg{display:flex;flex-wrap:wrap;gap:16px;align-items:flex-end}
        .rk-cfg .f{display:flex;flex-direction:column;gap:5px}
        .rk-cfg label{font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--fp-muted)}
        .rk-cfg input{width:150px;padding:8px 10px;border:1px solid var(--fp-border);border-radius:9px;background:var(--fp-surface,#fff);color:var(--fp-primary);font-size:.92rem}
        .rk-btn{display:inline-flex;align-items:center;gap:7px;padding:9px 15px;border-radius:10px;border:none;cursor:pointer;font-weight:800;font-size:.86rem;background:linear-gradient(135deg,#0B1220,#1E293B);color:#fff;box-shadow:0 12px 26px -14px rgba(11,18,32,.8);transition:transform .12s}
        .rk-btn:hover{transform:translateY(-1px)} .rk-btn.ghost{background:transparent;color:var(--fp-primary);border:1px solid var(--fp-border);box-shadow:none}
        .rk-btn:disabled{opacity:.5;cursor:default;transform:none}
        .rk-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:2px}
        .rk-title{font-weight:900;font-size:1.05rem;color:var(--fp-primary);display:flex;align-items:center;gap:8px}
        .rk-list{display:flex;flex-direction:column;gap:8px}
        .rk-item{border:1px solid var(--fp-border);border-radius:13px;overflow:hidden;background:var(--fp-surface,#fff);transition:box-shadow .15s,border-color .15s}
        .rk-item:hover{box-shadow:0 10px 26px -20px rgba(15,30,61,.55)}
        .rk-main{display:grid;grid-template-columns:14px 1.4fr 1.2fr .8fr 1.8fr auto auto;gap:12px;align-items:center;padding:12px 14px;cursor:pointer}
        @media(max-width:900px){.rk-main{grid-template-columns:14px 1fr auto;grid-auto-rows:auto}.rk-chauf,.rk-km,.rk-last{grid-column:2/4;font-size:.85rem}}
        .rk-dot{width:11px;height:11px;border-radius:50%;box-shadow:0 0 0 4px rgba(0,0,0,.04)}
        .rk-idcol{display:flex;flex-direction:column;gap:1px;min-width:0}
        .rk-plate{font-weight:800;color:var(--fp-primary);text-decoration:none;font-family:ui-monospace,monospace}
        .rk-plate:hover{color:var(--fp-accent);text-decoration:underline}
        .rk-model{font-size:.76rem;color:var(--fp-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
        .rk-chauf{font-size:.9rem;color:var(--fp-primary);min-width:0;overflow:hidden;text-overflow:ellipsis}
        .rk-km{font-weight:700;color:var(--fp-primary);white-space:nowrap}
        .rk-last{font-size:.85rem;color:var(--fp-primary)} .rk-since{color:var(--fp-muted)}
        .rk-pill{padding:4px 11px;border-radius:9999px;font-size:.74rem;font-weight:800;white-space:nowrap}
        .rk-actions{display:flex;align-items:center;gap:10px}
        .rk-ask{display:inline-flex;align-items:center;gap:5px;padding:5px 10px;border-radius:8px;border:1px solid var(--fp-border);background:var(--fp-surface,#fff);color:var(--fp-primary);font-weight:700;font-size:.78rem;cursor:pointer}
        .rk-ask:hover{border-color:var(--fp-accent);color:var(--fp-accent)}
        .rk-noemail{font-size:.72rem;color:#B45309}
        .rk-chev{color:var(--fp-muted);transition:transform .18s}
        .rk-item.open .rk-chev{transform:rotate(180deg)}
        .rk-detail{padding:4px 16px 14px 37px;border-top:1px dashed var(--fp-border);background:rgba(148,163,184,.05)}
        .rk-detail-head{font-size:.76rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--fp-muted);margin:10px 0 6px}
        .rk-hrow{display:flex;align-items:center;gap:10px;padding:5px 0;font-size:.88rem;color:var(--fp-primary);border-bottom:1px solid rgba(148,163,184,.14)}
        .rk-hrow:last-child{border-bottom:none}
        .rk-hdate{min-width:86px;color:var(--fp-muted)} .rk-delta{color:#15803D;font-weight:700}
        .rk-hchan{margin-left:auto;font-size:.72rem;color:var(--fp-muted)}
        .rk-empty{color:var(--fp-muted);text-align:center;padding:26px}
        .rk-edit{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:12px;padding-top:12px;border-top:1px dashed var(--fp-border)}
        .rk-edit label{font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--fp-muted)}
        .rk-edit input{width:130px;padding:8px 10px;border:1px solid var(--fp-border);border-radius:9px;background:var(--fp-surface,#fff);color:var(--fp-primary);font-size:.92rem}
        .rk-km-st{font-size:.8rem;font-weight:700}
      </style>
      <div class="rk-wrap">
        <div class="rk-tiles">
          ${tile(okPct + '%', 'Flotte à jour', 'linear-gradient(135deg,#0B1220,#1E293B)', '#22C55E')}
          ${tile(cnt.ajour, 'Relevés à jour', 'linear-gradient(135deg,#064E3B,#0F766E)', '#34D399')}
          ${tile(cnt.attente, 'En attente de réponse', 'linear-gradient(135deg,#7C2D12,#B45309)', '#FBBF24')}
          ${tile(manquants, 'Manquants / à relancer', 'linear-gradient(135deg,#7F1D1D,#9F1239)', '#FB7185')}
        </div>
        <div class="rk-card">
          <div class="rk-head" style="margin-bottom:12px"><div class="rk-title"><i data-lucide="sliders-horizontal" class="w-5 h-5" style="color:var(--fp-accent)"></i> Réglages des rappels km</div></div>
          <div class="rk-cfg">
            <div class="f"><label>Un relevé reste valable (jours)</label><input id="rk-seuil" type="number" min="1" step="1" value="${seuil}"></div>
            <div class="f"><label>Relance auto par mail si sans réponse (jours)</label><input id="rk-relance" type="number" min="1" step="1" value="${relance}"></div>
            <div class="f"><label>Tout le monde redonne son km à partir du…</label><input id="rk-debut" type="date" value="${cfg.releveKmDebut || ''}"></div>
            <button class="rk-btn" id="rk-save"><i data-lucide="check" class="w-4 h-4"></i> Enregistrer</button>
            <span id="rk-save-st" style="font-size:.8rem;color:var(--fp-muted)"></span>
          </div>
          <p style="font-size:.78rem;color:var(--fp-muted);margin:10px 0 0">Synchronisé sur tous tes appareils. <b>« Un relevé reste valable X jours »</b> = un véhicule est « à jour » tant qu'il a donné son km il y a moins de X jours ; passé ce délai il repasse « à faire ». <b>C'est une durée de validité, pas un « tout le monde doit répondre »</b> : plus le nombre est grand, plus les véhicules restent « à jour » longtemps. 👉 Pour <b>forcer TOUTE la flotte à redonner son km</b>, mets la <b>date du jour</b> dans « Tout le monde redonne son km à partir du… » : tous ceux qui n'ont pas donné leur km depuis cette date repassent « à faire ». La <b>relance auto par mail</b> renvoie tout seul la demande à ceux qui ne répondent pas au bout du délai. Réglages aussi dans Paramètres → Configuration.</p>
        </div>
        <div class="rk-card">
          <div class="rk-head">
            <div class="rk-title"><i data-lucide="gauge" class="w-5 h-5" style="color:var(--fp-accent)"></i> Suivi des relevés <span style="font-weight:400;color:var(--fp-muted);font-size:.85rem">— ${rows.length} véhicule(s)</span></div>
            <div style="display:flex;gap:8px;flex-wrap:wrap">
              <button class="rk-btn" id="rk-config" title="Choisir quels véhicules sont suivis pour le km (décocher = ne plus demander)"><i data-lucide="list-checks" class="w-4 h-4"></i> Configurer${nonSuivi ? ` (${nonSuivi} non suivi${nonSuivi > 1 ? 's' : ''})` : ''}</button>
              ${avecMail ? `<button class="rk-btn" id="rk-ask-all"><i data-lucide="send" class="w-4 h-4"></i> Demander aux manquants (${avecMail})</button>` : ''}
            </div>
          </div>
          <p style="font-size:.8rem;color:var(--fp-muted);margin:2px 0 14px">« À jour » = relevé reçu il y a ≤ ${seuil} j${cfg.releveKmDebut ? ' (et après le ' + (function(){try{return FP.date(cfg.releveKmDebut);}catch(e){return cfg.releveKmDebut;}})() + ')' : ''}. Clique une ligne pour voir l'historique et le km par période. Le QR à coller dans chaque voiture se génère depuis la fiche véhicule (bouton « QR km »). <b>Décoche un véhicule</b> pour ne plus jamais demander son km.</p>
          <div class="rk-list">
            ${loading ? '<div class="rk-empty">Chargement des relevés…</div>' : (sorted.length ? sorted.map(rowHTML).join('') : '<div class="rk-empty">Aucun véhicule en flotte.</div>')}
          </div>
        </div>
      </div>`;
    if (window.lucide) lucide.createIcons();
  }

  function openKmConfig() {
    const E = esc;
    const flotte = (D().vehicules || []).filter(v => !(FP.horsFlotte && FP.horsFlotte(v))).slice().sort((a, b) => (a.immat || '').localeCompare(b.immat || ''));
    const byId = (id) => flotte.find(v => String(v.id) === String(id));
    const rowHtml = (v) => {
      const on = !FP.kmSuivi || FP.kmSuivi(v);
      const ch = (v.chauffeur && v.chauffeur !== '—') ? E(v.chauffeur) : '—';
      return `<label style="display:flex;align-items:center;gap:10px;padding:9px 6px;border-bottom:1px solid var(--fp-border);cursor:pointer">
        <input type="checkbox" class="km-cfg-cb" data-id="${E(v.id)}" ${on ? 'checked' : ''} style="width:18px;height:18px;accent-color:var(--fp-accent);flex:none">
        <span style="flex:1;min-width:0"><span style="font-family:monospace;font-weight:700">${E(v.immat || '—')}</span><span style="color:var(--fp-muted);font-size:.85rem"> · ${E(v.marque || '')} ${E(v.modele || '')}</span><span style="display:block;color:var(--fp-muted);font-size:.78rem">${ch}</span></span>
      </label>`;
    };
    const ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;z-index:2147483000;background:rgba(15,23,42,.5);display:flex;align-items:center;justify-content:center;padding:16px';
    ov.innerHTML = `<div style="background:#fff;border-radius:16px;max-width:560px;width:100%;max-height:82vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 30px 80px -20px rgba(15,30,61,.5)">
      <div style="padding:16px 18px;border-bottom:1px solid var(--fp-border);display:flex;align-items:center;justify-content:space-between;gap:10px"><div style="font-weight:800;font-size:1.05rem">Suivre le km de quels véhicules&nbsp;?</div><button id="km-cfg-x" style="border:none;background:#f1f5f9;width:34px;height:34px;border-radius:50%;cursor:pointer;font-size:1.1rem;line-height:1">✕</button></div>
      <div style="padding:10px 14px;border-bottom:1px solid var(--fp-border);display:flex;gap:8px;align-items:center;flex-wrap:wrap"><input id="km-cfg-search" placeholder="Rechercher…" style="flex:1;min-width:140px;padding:8px 10px;border:1px solid var(--fp-border);border-radius:8px"><button class="btn btn-outline text-xs" id="km-cfg-all">Tout cocher</button><button class="btn btn-outline text-xs" id="km-cfg-none">Tout décocher</button></div>
      <div id="km-cfg-list" style="overflow:auto;padding:2px 14px">${flotte.map(rowHtml).join('') || '<p style="color:var(--fp-muted);padding:16px">Aucun véhicule.</p>'}</div>
      <div style="padding:12px 16px;border-top:1px solid var(--fp-border);text-align:right"><button class="btn btn-dark" id="km-cfg-done">Terminé</button></div>
    </div>`;
    document.body.appendChild(ov);
    const close = () => { ov.remove(); changed(); };
    ov.addEventListener('click', (e) => {
      if (e.target === ov || e.target.closest('#km-cfg-x') || e.target.closest('#km-cfg-done')) { close(); return; }
      const cb = e.target.closest('.km-cfg-cb');
      if (cb) { const v = byId(cb.getAttribute('data-id')); if (v && FP.kmSuiviSet) FP.kmSuiviSet(v, cb.checked); return; }
      const all = e.target.closest('#km-cfg-all'), none = e.target.closest('#km-cfg-none');
      if (all || none) {
        const on = !!all;
        const s = FP.settings.get(); const ex = Object.assign({}, s.kmSuiviExclus || {});
        flotte.forEach(v => { if (on) delete ex[v.id]; else ex[v.id] = true; });
        s.kmSuiviExclus = ex; FP.settings.save(s);
        ov.querySelectorAll('.km-cfg-cb').forEach(c => { c.checked = on; });
        return;
      }
    });
    const srch = ov.querySelector('#km-cfg-search');
    if (srch) srch.addEventListener('input', () => {
      const q = (FP.norm ? FP.norm(srch.value) : srch.value.toLowerCase()).trim();
      ov.querySelectorAll('#km-cfg-list label').forEach(l => { const t = FP.norm ? FP.norm(l.textContent) : l.textContent.toLowerCase(); l.style.display = (!q || t.includes(q)) ? '' : 'none'; });
    });
    setTimeout(() => { try { srch && srch.focus(); } catch (e) {} }, 50);
  }

  function openKmBlockersModal(v, targetKm, onDone) {
    const E = esc;
    const ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;z-index:2147483000;background:rgba(15,23,42,.5);display:flex;align-items:center;justify-content:center;padding:16px';
    const box = document.createElement('div');
    box.style.cssText = 'background:#fff;border-radius:16px;max-width:600px;width:100%;max-height:86vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 30px 80px -20px rgba(15,30,61,.5)';
    ov.appendChild(box);
    const close = () => ov.remove();
    function correct(f, newKm) {
      f.km = newKm;
      try { if (FP.persist) FP.persist.update('factures', f.id, { km: newKm }); } catch (e) {}
      try { if (FP.recomputeVehiculeFromFactures) FP.recomputeVehiculeFromFactures(v, (window.FP_DATA && FP_DATA.factures) || []); } catch (e) {}
      draw();
    }
    async function saveReleve() {
      const KC = window.FP && FP.kmCollecte; if (!KC) return;
      const r = await KC.saisieManuelle(v, targetKm);
      close();
      if (onDone) onDone(r);
    }
    function draw() {
      const blockers = FP.blockingRevisionFactures ? FP.blockingRevisionFactures(v, targetKm) : [];
      const rowsB = blockers.map(f => `
        <div class="kb-row" data-fid="${E(f.id)}" style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:11px 0;border-bottom:1px solid var(--fp-border)">
          <div style="flex:1;min-width:140px"><div style="font-weight:700">${E(f.fournisseur || f.description || "Facture d'entretien")}</div><div style="font-size:.8rem;color:var(--fp-muted)">${f.date ? FP.dateNum(f.date) : 'sans date'}${f.numeroFacture ? ' · n° ' + E(f.numeroFacture) : ''} · <b style="color:#B91C1C">${FP.num(f.km)} km</b></div></div>
          <input type="number" min="0" step="1" placeholder="km réel" class="kb-input" style="width:110px;padding:8px 10px;border:1px solid var(--fp-border);border-radius:9px">
          <button class="rk-btn kb-fix" type="button" style="padding:8px 12px">Corriger</button>
          <button class="rk-btn ghost kb-clear" type="button" style="padding:8px 12px">Vider le km</button>
        </div>`).join('');
      box.innerHTML = `
        <div style="padding:16px 18px;border-bottom:1px solid var(--fp-border);display:flex;align-items:center;justify-content:space-between;gap:10px"><div style="font-weight:800;font-size:1.05rem">🔧 Une facture bloque ce km</div><button class="kb-x" style="border:none;background:#f1f5f9;width:34px;height:34px;border-radius:50%;cursor:pointer;font-size:1.1rem;line-height:1">✕</button></div>
        <div style="padding:14px 18px;overflow:auto"><p style="font-size:.9rem;color:var(--fp-primary);margin:0 0 12px;line-height:1.5">Tu veux mettre <b>${FP.num(targetKm)} km</b> sur <b>${E(v.immat || '')}</b>, mais une <b>facture d'entretien</b> indique un km <b>plus élevé</b> — l'appli empêche le compteur de descendre sous le km de la <b>dernière révision</b>. Corrige (ou vide) le km de cette facture pour débloquer :</p>${blockers.length ? rowsB : '<div style="padding:14px;border-radius:12px;background:rgba(21,128,61,.1);color:#15803D;font-weight:700">✓ Plus aucune facture ne bloque — tu peux enregistrer le relevé.</div>'}</div>
        <div style="padding:12px 16px;border-top:1px solid var(--fp-border);display:flex;justify-content:space-between;gap:10px"><button class="rk-btn ghost kb-cancel" type="button">Annuler</button><button class="rk-btn kb-save" type="button" ${blockers.length ? 'disabled' : ''}>Enregistrer le relevé (${FP.num(targetKm)} km)</button></div>`;
      if (window.lucide) lucide.createIcons();
    }
    box.addEventListener('click', (e) => {
      if (e.target.closest('.kb-x') || e.target.closest('.kb-cancel')) { close(); return; }
      if (e.target.closest('.kb-save')) { saveReleve(); return; }
      const fix = e.target.closest('.kb-fix'), clr = e.target.closest('.kb-clear');
      if (fix || clr) {
        const row = e.target.closest('.kb-row'); if (!row) return;
        const f = ((window.FP_DATA && FP_DATA.factures) || []).find(x => String(x.id) === String(row.getAttribute('data-fid')));
        if (!f) return;
        if (clr) { correct(f, null); return; }
        const nk = Math.round(Number(row.querySelector('.kb-input').value));
        if (!Number.isFinite(nk) || nk < 0) { alert('Entre un km valide (ou clique « Vider le km »).'); return; }
        correct(f, nk);
      }
    });
    ov.addEventListener('click', (e) => { if (e.target === ov) close(); });
    draw();
    document.body.appendChild(ov);
  }

  function wire(box) {
    box.addEventListener('click', async (e) => {
      if (e.target.closest('#rk-save')) {
        const st = box.querySelector('#rk-save-st');
        if (!(window.FP && FP.settings)) { if (st) st.textContent = 'Réglages indisponibles.'; return; }
        if (FP.canManageSociete && !FP.canManageSociete()) { if (st) { st.textContent = '⚠️ Réservé à l\'administrateur.'; st.style.color = '#B91C1C'; } return; }
        const gi = id => { const el = box.querySelector('#' + id); return el ? el.value : ''; };
        const s = FP.settings.get() || {}; s.notif = Object.assign({}, s.notif || {}, {
          releveKmJours: Math.max(1, parseInt(gi('rk-seuil'), 10) || 45),
          releveKmRelanceJours: Math.max(1, parseInt(gi('rk-relance'), 10) || 7),
          releveKmDebut: gi('rk-debut') || ''
        });
        try { FP.settings.save(s); if (st) { st.textContent = '✓ Enregistré (synchronisé).'; st.style.color = '#15803D'; } if (_onChange) _onChange(); }
        catch (err) { if (st) { st.textContent = '⚠️ Échec.'; st.style.color = '#B91C1C'; } }
        return;
      }
      if (e.target.closest('#rk-config')) { openKmConfig(); return; }
      if (e.target.closest('#rk-ask-all')) {
        const KC = window.FP && FP.kmCollecte; if (!KC) return;
        const cibles = rkBuildRows().filter(r => r.statut !== 'ajour' && r.email).map(r => r.v);
        if (!cibles.length) return;
        if (FP.confirm && !(await FP.confirm(`Envoyer une demande de relevé km à ${cibles.length} chauffeur(s) par e-mail ?`))) return;
        const b = FP.busy ? FP.busy('Envoi… 0/' + cibles.length) : null;
        const res = await KC.sendBatch(cibles, (d, t) => { if (b) b.update('Envoi… ' + d + '/' + t); });
        if (b) { const m = `📩 ${res.sent.length} envoyée(s)` + (res.failed.length ? ` · ${res.failed.length} échec(s)` : ''); res.failed.length ? b.fail(m) : b.done(m); }
        paint();
        return;
      }
      const ask = e.target.closest('[data-rk-ask]');
      if (ask) {
        e.stopPropagation();
        const KC = window.FP && FP.kmCollecte; if (!KC) return;
        const v = (D().vehicules || []).find(x => x.id === ask.getAttribute('data-rk-ask'));
        if (!v) return;
        const b = FP.busy ? FP.busy('Envoi de la demande…') : null;
        const r = await KC.send(v);
        if (r.ok) { if (b) b.done('📩 Demande envoyée à ' + r.email); } else { if (b) b.fail('⚠️ ' + (r.error || 'Échec')); }
        paint();
        return;
      }
      const kmSave = e.target.closest('[data-rk-km-save]');
      if (kmSave) {
        e.stopPropagation();
        const KC = window.FP && FP.kmCollecte; if (!KC) return;
        const id = kmSave.getAttribute('data-rk-km-save');
        const v = (D().vehicules || []).find(x => x.id === id); if (!v) return;
        const inp = box.querySelector('[data-rk-km="' + (window.CSS && CSS.escape ? CSS.escape(id) : id) + '"]');
        const st = box.querySelector('[data-rk-km-st="' + (window.CSS && CSS.escape ? CSS.escape(id) : id) + '"]');
        const km = inp ? Math.round(Number(inp.value)) : NaN;
        if (!Number.isFinite(km) || km <= 0) { if (st) { st.textContent = 'Entre un km valide.'; st.style.color = '#B91C1C'; } return; }
        const cur = FP.kmActuel ? FP.kmActuel(v) : (Number(v.km) || 0);
        if (km < cur) {
          const blockers = FP.blockingRevisionFactures ? FP.blockingRevisionFactures(v, km) : [];
          if (blockers.length) { if (st) { st.textContent = ''; } openKmBlockersModal(v, km, () => { changed(); }); return; }
          if (FP.confirm && !(await FP.confirm(`Le km saisi (${FP.num(km)}) est INFÉRIEUR au km actuel (${FP.num(cur)}). Confirmer la correction à la baisse ?`))) return;
        }
        if (st) { st.textContent = 'Enregistrement…'; st.style.color = 'var(--fp-muted)'; }
        kmSave.disabled = true;
        const r = await KC.saisieManuelle(v, km);
        kmSave.disabled = false;
        if (r.ok) { if (st) { st.textContent = '✓ Enregistré (synchronisé).'; st.style.color = '#15803D'; } changed(); }
        else if (st) { st.textContent = '⚠️ ' + (r.error || 'Échec'); st.style.color = '#B91C1C'; }
        return;
      }
      const tog = e.target.closest('[data-rk-toggle]');
      if (tog) {
        const item = tog.closest('.rk-item'); if (!item) return;
        const det = item.querySelector('.rk-detail');
        if (det) { det.hidden = !det.hidden; item.classList.toggle('open', !det.hidden); }
      }
    });
  }

  return {
    mount(container, opts) {
      if (!container) return;
      _box = container; _onChange = (opts && opts.onChange) || null;
      if (!container.dataset.rkWired) { container.dataset.rkWired = '1'; wire(container); }
      paint();
    }
  };
})();

// Détection carburant / péages — UNE seule règle partagée (dashboard, factures, statistiques) :
// par TYPE (carburant/peage/ulys) OU par FOURNISSEUR (Ulys, TotalEnergies). Avant, un carburant
// sans type mais avec le bon fournisseur était compté à un endroit et pas à l'autre.
FP.estUlys = (f) => { const n = s => String(s || '').toLowerCase(); return n(f && f.type) === 'ulys' || /\bulys\b/.test(n(f && f.fournisseur)); };
FP.estTotalFleet = (f) => { if (FP.estUlys(f)) return false; const n = s => String(s || '').toLowerCase(); const t = n(f && f.type); if (t === 'carburant' || t === 'peage') return true; return /total\s*energies|totalenergies/.test(n(f && f.fournisseur)); };
FP.estCarburantPeage = (f) => FP.estUlys(f) || FP.estTotalFleet(f);
// ⚠️ HELPER CANONIQUE — parse un montant saisi/OCR : gère l'espace (dont insécable), le point ET la
// virgule décimale. « 1 466,48 » / « 1 466.48 » / « 1466,48 » → 1466.48. À utiliser PARTOUT au lieu de
// parseFloat(x.replace(',','.')) qui casse sur « 1 500 » (→ 1). Renvoie null si vide/non numérique.
FP.parseMontant = (s) => { if (s == null || s === '') return null; const n = parseFloat(String(s).replace(/\s/g, '').replace(',', '.')); return isNaN(n) ? null : n; };
// ⚠️ HELPER CANONIQUE — normalise une immatriculation pour la COMPARER (majuscules, retrait de tout ce
// qui n'est pas alphanumérique : tirets, espaces, points). « AB-123-CD », « ab 123 cd », « AB123CD » →
// « AB123CD ». À utiliser pour TOUT match facture↔véhicule / amende↔véhicule / document↔véhicule.
FP.normImmat = (s) => String(s == null ? '' : s).toUpperCase().replace(/[^A-Z0-9]/g, '');
// ⚠️ SOURCE UNIQUE — AFFICHAGE d'une plaque avec les tirets (plus propre), quel que soit le format
// stocké. On NE TOUCHE PAS au stockage ni au matching (toujours via normImmat) : c'est purement visuel.
//   • SIV (depuis 2009) : AB-123-CD  → « AA-999-AA »
//   • FNI (ancien)      : 1234-AB-56 → « 999(9)-AA(A)-99 »
// Si le format n'est pas reconnu, on renvoie la plaque telle quelle (en majuscules).
FP.immatFmt = (s) => {
  if (s == null || s === '') return '';
  const raw = String(s).trim();
  if (raw.indexOf('-') >= 0) return raw.toUpperCase();          // déjà avec tirets → on garde
  const n = FP.normImmat(raw);
  let m = n.match(/^([A-Z]{2})([0-9]{3})([A-Z]{2})$/);          // SIV : AB123CD
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = n.match(/^([0-9]{1,4})([A-Z]{2,3})([0-9]{2})$/);          // FNI : 1234AB56
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  return raw.toUpperCase();
};
// ⚠️ SOURCE UNIQUE — deux plaques « égales » quel que soit le format (min/maj, tirets, espaces).
FP.immatEq = (a, b) => { const x = FP.normImmat(a); return !!x && x === FP.normImmat(b); };
// ⚠️ SOURCE UNIQUE — retrouve LE véhicule par sa plaque, tolérant à TOUS les formats. À utiliser
// PARTOUT où on relie un enregistrement (facture, sinistre, amende, contrat…) à un véhicule, plutôt
// qu'un `.find(v => v.immat === x)` brut qui rate « HL724CD » vs « HL-724-CD ».
FP.vehByImmat = (immat, list) => {
  const k = FP.normImmat(immat); if (!k) return null;
  const vs = list || (window.FP_DATA && FP_DATA.vehicules) || (window.data && data.vehicules) || [];
  return vs.find(v => v && FP.normImmat(v.immat) === k) || null;
};
// ⚠️ HELPER CANONIQUE — prime d'assurance annuelle TTC d'un véhicule. La prime est stockée en OBJET
// { ht, ttc } (settings.assurancePrimes[id]) — ne JAMAIS faire Number(prime) (→ NaN). Renvoie le TTC (nombre) ou 0.
// La prime est keyée par IMMATRICULATION (comparaison normalisée, comme dans Contrats), PAS par id.
FP.primeVeh = (v) => {
  try {
    const map = FP.settings.get().assurancePrimes || {};
    const k = FP.normImmat(v && v.immat); if (!k) return 0;
    let p = map[v.immat];
    if (p == null) { for (const key in map) { if (FP.normImmat(key) === k) { p = map[key]; break; } } }
    if (p == null) return 0;
    return (typeof p === 'object') ? (Number(p.ttc) || 0) : (Number(p) || 0);
  } catch (e) { return 0; }
};
// ⚠️ HELPER CANONIQUE — total annuel des primes d'assurance du parc POSSÉDÉ (exclut les vendus).
// Logique (identique à Contrats/Budget) : si des primes PAR VÉHICULE sont saisies et couvrent au
// moins un véhicule possédé (somme > 0) → on somme ces primes ; SINON on retombe sur la prime
// « flotte » globale saisie à la main (settings.assurancePrimeAnnuelle). Avant, ce helper ne
// sommait que les primes par véhicule → il renvoyait 0 quand seule la prime flotte était saisie.
FP.assuranceAnnuelle = (vehicules) => {
  const s = (FP.settings && FP.settings.get) ? (FP.settings.get() || {}) : {};
  const primes = (s.assurancePrimes && typeof s.assurancePrimes === 'object') ? s.assurancePrimes : {};
  const owned = (vehicules || []).filter(v => !FP.horsFlotte(v));
  if (Object.keys(primes).length) {
    let t = 0; owned.forEach(v => { t += FP.primeVeh(v); });
    if (t > 0) return t;
  }
  const flotte = Number(s.assurancePrimeAnnuelle); return Number.isFinite(flotte) ? flotte : 0;
};
// ⚠️ HELPER CANONIQUE — total annuel TVS de la flotte POSSÉDÉE. MÊME périmètre que le leasing et
// que FP.assuranceAnnuelle : on exclut tout véhicule HORS FLOTTE (vendu, cédé, restitué, archivé,
// hors service) via FP.horsFlotte — un véhicule qu'on ne possède plus n'engendre plus ni assurance
// ni TVS. tvsDetail renvoie déjà 0 si non applicable (élec, hors-catégorie…).
// À utiliser PARTOUT où l'on somme la TVS de la flotte (dashboard, budget, stats, contrats, écran,
// recherche) — un seul périmètre, plus de reduce recopié à la main dans chaque page.
FP.tvsAnnuelleFlotte = (vehicules) => (vehicules || []).filter(v => !FP.horsFlotte(v))
  .reduce((s, v) => { const d = FP.tvsDetail(v); return s + (d && d.applicable && d.total != null ? d.total : 0); }, 0);

// ============================================================================
// AVANTAGE EN NATURE (AEN) — méthode FORFAIT (barème URSSAF, national). DEUX barèmes coexistent :
//  • ANCIEN  (véhicule mis à disposition AVANT le 01/02/2025) : acheté 9 %/6 %, loué 30 %, abatt. élec 50 %.
//  • NOUVEAU (mis à disposition DEPUIS le 01/02/2025 — réforme) : acheté 15 %/10 %, loué 50 %, abatt. élec 70 %.
// PP choisit AUTOMATIQUEMENT le bon barème selon la DATE DE MISE À DISPOSITION (début d'affectation au
// conducteur, sinon 1re mise en circulation), avec override possible par véhicule (settings.aenBareme[id]
// ∈ 'ancien'|'nouveau'). Taux 100 % réglables (settings.aen, synchronisés). Source unique = FP.aenDetail.
FP.AEN_DEFAULTS = {
  actif: true,
  carburantFourni: true,   // l'employeur fournit le carburant (global ; flottes à carte carburant)
  inclureAssurance: true,  // inclure la prime d'assurance dans le coût global annuel du véhicule loué
  bascule: '2025-02-01',   // date charnière ancien ↔ nouveau barème
  ancien:  { tauxAcheteMoins5: 9,  tauxAchetePlus5: 6,  supplAchatCarb: 3,  tauxLoue: 30, supplLoueCarb: 10, abattementElec: 50, plafondElecAnnuel: 1964 },
  nouveau: { tauxAcheteMoins5: 15, tauxAchetePlus5: 10, supplAchatCarb: 5,  tauxLoue: 50, supplLoueCarb: 17, abattementElec: 70, plafondElecAnnuel: 4582 }
};
FP.aenConfig = () => {
  try {
    const s = FP.settings.get().aen || {};
    const c = Object.assign({}, FP.AEN_DEFAULTS, s);
    c.ancien = Object.assign({}, FP.AEN_DEFAULTS.ancien, s.ancien || {});
    c.nouveau = Object.assign({}, FP.AEN_DEFAULTS.nouveau, s.nouveau || {});
    return c;
  } catch (e) { const c = Object.assign({}, FP.AEN_DEFAULTS); c.ancien = Object.assign({}, FP.AEN_DEFAULTS.ancien); c.nouveau = Object.assign({}, FP.AEN_DEFAULTS.nouveau); return c; }
};
// Date de mise à DISPOSITION au salarié (≈ début d'affectation ; repli sur 1re mise en circulation).
FP.aenDateMiseADispo = (v) => {
  try { if (FP.affectations && FP.affectations.debutAffiche) { const d = FP.affectations.debutAffiche(v); if (d) { const dd = new Date(d); if (!isNaN(dd)) return dd; } } } catch (e) {}
  if (v && v.dateMiseEnCirculation) { const dd = new Date(v.dateMiseEnCirculation); if (!isNaN(dd)) return dd; }
  return null;
};
// Quel barème pour ce véhicule ? Override par véhicule prioritaire, sinon selon la date vs bascule.
FP.aenBaremePour = (v, cfg) => {
  cfg = cfg || FP.aenConfig();
  try { const ov = (FP.settings.get().aenBareme || {})[v && v.id]; if (ov === 'ancien' || ov === 'nouveau') return ov; } catch (e) {}
  const d = FP.aenDateMiseADispo(v);
  const bascule = new Date(cfg.bascule || '2025-02-01');
  if (d && !isNaN(d) && !isNaN(bascule) && d < bascule) return 'ancien';
  return 'nouveau';
};
// Renvoie le détail AEN d'un véhicule, ou null si non calculable / non concerné.
//   { applicable, method:'acheté'|'loué', bareme:'ancien'|'nouveau', elec, base, taux, brutAnnuel, abattement, netAnnuel, netMensuel, reason? }
FP.aenDetail = (v) => {
  if (!v || (FP.estVendu && FP.estVendu(v))) return null;
  const cfg = FP.aenConfig();
  if (!cfg.actif) return null;
  const bareme = FP.aenBaremePour(v, cfg);
  const b = cfg[bareme] || FP.AEN_DEFAULTS[bareme];
  const carbFourni = !!cfg.carburantFourni;
  const elec = (FP.normCarburant ? FP.normCarburant(v.carburant) : v.carburant) === 'Électrique';
  const c = FP.leasingContrat ? FP.leasingContrat(v.immat) : null;
  // ⚠️ SOURCE UNIQUE du loyer : FP.leasingCoutContrat couvre le forfait ET les contrats LLD saisis
  // dans l'onglet Contrats (localeaseContrats — Ayvens/Localease/BPCE…). L'AEN doit lire le loyer
  // au MÊME endroit que le KPI « Loyer » de l'en-tête, sinon un véhicule dont le loyer est renseigné
  // dans Contrats affichait à tort « loyer inconnu ».
  const cc = FP.leasingCoutContrat ? FP.leasingCoutContrat(v.immat) : null;
  const cActif = c && (!FP.leasingActif || FP.leasingActif(c));
  let base = 0, taux = 0, method, loyerAnnuel = null;
  if (cActif || cc) {
    const info = FP.leasingInfo ? FP.leasingInfo(v) : null;
    const loyer = (cc && cc.loyerMois != null) ? Number(cc.loyerMois)
                : (info && info.loyer != null) ? info.loyer
                : (c && c.loyer != null) ? Number(c.loyer) : null;
    if (loyer == null || !(loyer > 0)) return { applicable: false, method: 'loué', bareme, elec, reason: "loyer inconnu" };
    loyerAnnuel = loyer * 12;
    const assur = cfg.inclureAssurance ? (FP.primeVeh ? (FP.primeVeh(v) || 0) : 0) : 0;
    base = loyerAnnuel + assur;
    taux = Number(b.tauxLoue) + (carbFourni ? Number(b.supplLoueCarb) : 0);
    method = 'loué';
  } else {
    const val = Number(v.valeurAchat) || 0;
    if (!(val > 0)) return { applicable: false, method: 'acheté', bareme, elec, reason: "valeur d'achat inconnue" };
    base = val;
    const mec = v.dateMiseEnCirculation ? new Date(v.dateMiseEnCirculation) : null;
    const ageAns = (mec && !isNaN(mec)) ? (Date.now() - mec.getTime()) / (365.25 * 864e5) : null;
    const moins5 = (ageAns == null || ageAns < 5);
    taux = (moins5 ? Number(b.tauxAcheteMoins5) : Number(b.tauxAchetePlus5)) + (carbFourni ? Number(b.supplAchatCarb) : 0);
    method = 'acheté';
  }
  const brutAnnuel = base * taux / 100;
  let abattement = 0;
  if (elec && Number(b.abattementElec) > 0) {
    abattement = brutAnnuel * Number(b.abattementElec) / 100;
    if (Number(b.plafondElecAnnuel) > 0 && abattement > Number(b.plafondElecAnnuel)) abattement = Number(b.plafondElecAnnuel);
  }
  const netAnnuel = Math.max(0, brutAnnuel - abattement);
  return { applicable: true, method, bareme, elec, base, taux, brutAnnuel, abattement, netAnnuel, netMensuel: netAnnuel / 12, carbFourni, loyerAnnuel };
};
// Total AEN annuel de la flotte (véhicules AVEC conducteur affecté = usage privé possible).
FP.aenAnnuelFlotte = (vehicules) => (vehicules || []).reduce((s, v) => {
  const ch = v && v.chauffeur && String(v.chauffeur).trim();
  const excl = ['', '—', 'x', 'X', 'Siège', 'Dépôt', 'Navette', 'VENDU', 'Fenwick'];
  if (!ch || excl.includes(String(v.chauffeur).trim())) return s;
  const d = FP.aenDetail(v);
  return s + (d && d.applicable ? d.netAnnuel : 0);
}, 0);
// ⚠️ HELPER CANONIQUE — loyer ANNUEL total des contrats Localease/Ayvens (LLD) enregistrés
// (settings.localeaseContrats, synchronisé par société). Même calcul que la page Contrats (loyer courant
// = offre + avenant, sinon loyer de base ; override loyer par plaque prioritaire) ×12. Sert à ce que le
// leasing du Budget/écran corresponde à celui des Contrats (avant, le Budget ratait les LLD).
FP.leasingLocaleaseAnnuel = function (data) {
  try {
    const list = FP.settings.get().localeaseContrats;
    if (!Array.isArray(list)) return 0;
    const ov = FP.getLeasingOverrides ? FP.getLeasingOverrides() : {};
    // Index plaque → véhicule pour exclure les véhicules SORTIS (vendu/restitué/hors service) — cohérent TCO.
    const vehByImmat = {}; try { (((data || {}).vehicules) || (window.FP_DATA && window.FP_DATA.vehicules) || []).forEach(v => { const k = FP.normImmat(v && v.immat || ''); if (k) vehByImmat[k] = v; }); } catch (e) {}
    // ⚠️ Anti-doublon par PLAQUE : un même véhicule ne compte qu'UNE fois, même si deux contrats LLD ont été
    // saisis pour sa plaque (ressaisie / 2e appareil) — sinon le loyer annuel est compté en DOUBLE (+ ligne
    // dupliquée). Le dernier contrat saisi pour une plaque l'emporte. (Règle anti-doublon / « une info = une fois ».)
    const _byPlate = {}, _noPlate = [];
    list.forEach(c => { const k = FP.normImmat(c && c.immat || ''); if (k) _byPlate[k] = c; else _noPlate.push(c); });
    const mens = Object.keys(_byPlate).map(k => _byPlate[k]).concat(_noPlate).reduce((s, c) => {
      // Contrat LLD terminé (échéance connue et dépassée) → on ne projette plus son loyer annuel.
      if (FP.leasingTermine && FP.leasingTermine(c)) return s;
      const _v = vehByImmat[FP.normImmat(c && c.immat || '')];
      if (_v && FP.horsFlotte(_v)) return s; // véhicule sorti de la flotte → plus de loyer projeté
      const ik = String(c.immat || '').toUpperCase();
      const o = (ik && ov[ik]) ? ov[ik].loyer : null;
      const base = (o != null && o !== '') ? Number(o) : c.loyerTTC;
      const off = FP.leasingLoyerCourant ? FP.leasingLoyerCourant({ loyer: base, avenants: c.avenants }) : null;
      return s + (off != null ? off : (Number(base) || 0));
    }, 0);
    return mens * 12;
  } catch (e) { return 0; }
};
// ⚠️ HELPERS CANONIQUES — leasing de la flotte (mêmes règles que la page Contrats, qui reste la
// référence). Objectif : que Budget/Statistiques comptent le leasing EXACTEMENT comme Contrats
// (avant, Budget ne voyait que les véhicules avec une offre de loyer → il ratait ceux détectés par
// le PROPRIÉTAIRE (loueur) ou par repli sur la MÉDIANE des factures 'leasing').
// Loueurs de leasing configurés (settings.loueurs + repli profil société).
FP.leasingLoueurs = () => {
  let list = [];
  try { const s = FP.settings.get(); if (Array.isArray(s.loueurs)) list = s.loueurs; } catch (e) {}
  list = (list || []).filter(l => l && (String(l.nom || '').trim() || String(l.prop || '').trim()));
  const prof = (FP.societeProfil ? FP.societeProfil() : {}) || {};
  const propProfil = String(prof.proprietaireLeasing || prof.loueurNom || '').trim();
  if (propProfil) {
    const couvert = list.some(l => String(l.prop || '').trim().toLowerCase() === propProfil.toLowerCase());
    if (!couvert) list = [...list, { nom: prof.loueurNom || 'Leasing', prop: propProfil }];
  }
  if (list.length) return list;
  if (prof.loueurNom) return [{ nom: prof.loueurNom, prop: propProfil }];
  return [];
};
// Étiquettes « propriétaire » qui désignent un véhicule en leasing.
FP.leasingProps = () => FP.leasingLoueurs().map(l => String(l.prop || '').trim().toLowerCase()).filter(Boolean);
// Loyer mensuel BPCE total de la flotte (offre courante sinon médiane des factures 'leasing'). HORS Localease.
FP.leasingMensuelFlotte = (data) => {
  data = data || {};
  const actifs = (data.vehicules || []).filter(v => !FP.horsFlotte(v));
  const byVeh = {};
  (data.factures || []).filter(f => f.type === 'leasing').forEach(f => {
    const k = f.vehiculeImmat; if (!k) return;
    (byVeh[k] = byVeh[k] || []); if ((f.montantTTC || 0) > 0) byVeh[k].push(f.montantTTC);
  });
  const median = arr => { if (!arr || !arr.length) return null; const s = [...arr].sort((a, b) => a - b); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
  const props = FP.leasingProps();
  const immats = new Set([
    ...actifs.filter(v => { const p = String(v.proprietaire || '').trim().toLowerCase(); return p && props.includes(p); }).map(v => v.immat),
    ...Object.keys(byVeh),
  ]);
  // ⚠️ ANTI-DOUBLE-COMPTAGE : les plaques ayant un contrat LLD (settings.localeaseContrats) sont déjà
  // comptées par FP.leasingLocaleaseAnnuel → on les EXCLUT ici (sinon leur loyer, aussi présent en
  // factures 'leasing', serait compté deux fois dans le total Budget/Contrats).
  const lldSet = new Set();
  try { (FP.settings.get().localeaseContrats || []).forEach(c => { const k = FP.normImmat(c && c.immat || ''); if (k) lldSet.add(k); }); } catch (e) {}
  // Index plaque → véhicule (pour exclure les véhicules SORTIS de la flotte : vendu/restitué/hors service).
  const vehByImmat = {}; (data.vehicules || []).forEach(v => { const k = FP.normImmat(v && v.immat || ''); if (k) vehByImmat[k] = v; });
  let mens = 0;
  immats.forEach(immat => {
    if (lldSet.has(FP.normImmat(immat || ''))) return; // déjà compté par leasingLocaleaseAnnuel
    const _v = vehByImmat[FP.normImmat(immat || '')];
    if (_v && FP.horsFlotte(_v)) return; // véhicule vendu/restitué/sorti → on ne projette plus son loyer (cohérent TCO)
    const c = FP.leasingContrat ? FP.leasingContrat(immat) : null;
    if (c && FP.leasingTermine && FP.leasingTermine(c)) return; // contrat fini → plus de loyer projeté
    const off = (c && FP.leasingLoyerCourant) ? FP.leasingLoyerCourant(c) : null;
    const m = (off != null) ? off : median(byVeh[immat]);
    if (m > 0) mens += m;
  });
  return mens;
};
// ⚠️ SOURCE UNIQUE — MALUS écologique (coût UNIQUE, payé une seule fois au départ du contrat de
// leasing). Deux sources possibles selon le type de ligne : override/base BPCE via FP.leasingContrat,
// OU le contrat Localease/Ayvens (settings.localeaseContrats[].malus). FP.leasingMalus(v|immat) renvoie
// le malus (€) d'UN véhicule (0 si aucun) ; les totaux flotte ci-dessous s'appuient dessus.
FP.leasingMalus = (v) => {
  try {
    const immat = (typeof v === 'string') ? v : (v && v.immat);
    if (!immat) return 0;
    const key = String(immat).trim().toUpperCase();
    const c = FP.leasingContrat ? FP.leasingContrat(immat) : null;
    if (c && c.malus != null && c.malus !== '' && +c.malus > 0) return +c.malus;
    // Repli : override brut (le contrat peut ne pas avoir km/début → leasingContrat renvoie null).
    try { const ov = (FP.getLeasingOverrides ? FP.getLeasingOverrides() : {})[key]; if (ov && +ov.malus > 0) return +ov.malus; } catch (e) {}
    // Contrat Localease/Ayvens rattaché par plaque.
    const list = (FP.settings.get().localeaseContrats) || [];
    const k = FP.normImmat(immat);
    for (const lc of list) { if (lc && lc.immat && FP.normImmat(lc.immat) === k && +lc.malus > 0) return +lc.malus; }
  } catch (e) {}
  return 0;
};
// Durée (mois) du contrat de leasing d'un véhicule — pour amortir le malus sur la vie du contrat.
FP._leasingDureeMois = (v) => {
  try {
    const immat = (typeof v === 'string') ? v : (v && v.immat);
    const c = FP.leasingContrat ? FP.leasingContrat(immat) : null;
    if (c && +c.dureeMois > 0) return +c.dureeMois;
    const list = (FP.settings.get().localeaseContrats) || []; const k = FP.normImmat(immat);
    for (const lc of list) { if (lc && lc.immat && FP.normImmat(lc.immat) === k) { const d = +(lc.dureeMois || lc.duree); if (d > 0) return d; } }
  } catch (e) {}
  return 36;
};
// MALUS TOTAL de la flotte (coût unique, sur toute la vie des contrats) — pour « engagement » et TCO.
// Dédup par plaque, exclut les véhicules vendus/hors flotte et les contrats terminés.
FP.leasingMalusFlotte = (data) => {
  data = data || {}; let total = 0; const seen = new Set();
  try {
    const vehs = data.vehicules || [];
    // 1) Contrats Localease/Ayvens
    ((FP.settings.get().localeaseContrats) || []).forEach(c => {
      if (!c || !(+c.malus > 0)) return;
      if (FP.leasingTermine && FP.leasingTermine(c)) return;
      const k = c.immat ? FP.normImmat(c.immat) : '';
      if (k) { const v = vehs.find(x => FP.normImmat(x.immat) === k); if (v && FP.horsFlotte && FP.horsFlotte(v)) return; if (seen.has(k)) return; seen.add(k); }
      total += +c.malus;
    });
    // 2) Véhicules BPCE (override/base) non déjà comptés
    vehs.filter(v => !(FP.horsFlotte && FP.horsFlotte(v))).forEach(v => {
      const k = FP.normImmat(v.immat); if (!k || seen.has(k)) return;
      const c = FP.leasingContrat ? FP.leasingContrat(v.immat) : null;
      const m = FP.leasingMalus(v); if (!(m > 0)) return;
      if (c && FP.leasingTermine && FP.leasingTermine(c)) return;
      seen.add(k); total += m;
    });
  } catch (e) {}
  return total;
};
// MALUS ANNUEL AMORTI de la flotte = Σ (malus × 12 / durée) — le coût unique réparti sur la durée du
// contrat, pour un « coût annuel » réaliste (sinon une année serait gonflée par le malus complet).
FP.leasingMalusAnnuelFlotte = (data) => {
  data = data || {}; let total = 0; const seen = new Set();
  try {
    const vehs = data.vehicules || [];
    ((FP.settings.get().localeaseContrats) || []).forEach(c => {
      if (!c || !(+c.malus > 0)) return;
      if (FP.leasingTermine && FP.leasingTermine(c)) return;
      const k = c.immat ? FP.normImmat(c.immat) : '';
      if (k) { const v = vehs.find(x => FP.normImmat(x.immat) === k); if (v && FP.horsFlotte && FP.horsFlotte(v)) return; if (seen.has(k)) return; seen.add(k); }
      const d = +(c.dureeMois || c.duree) || 36; total += (+c.malus) * 12 / d;
    });
    vehs.filter(v => !(FP.horsFlotte && FP.horsFlotte(v))).forEach(v => {
      const k = FP.normImmat(v.immat); if (!k || seen.has(k)) return;
      const c = FP.leasingContrat ? FP.leasingContrat(v.immat) : null;
      const m = FP.leasingMalus(v); if (!(m > 0)) return;
      if (c && FP.leasingTermine && FP.leasingTermine(c)) return;
      seen.add(k); total += m * 12 / FP._leasingDureeMois(v);
    });
  } catch (e) {}
  return total;
};
// Coût annuel leasing total = BPCE (× 12) + Localease/Ayvens (déjà annuel) + malus amorti (coût unique
// réparti sur la durée). Source unique flotte (Budget, dashboard, Contrats lisent ce même total).
FP.leasingAnnuelFlotte = (data) => FP.leasingMensuelFlotte(data) * 12 + (FP.leasingLocaleaseAnnuel ? FP.leasingLocaleaseAnnuel(data) : 0) + FP.leasingMalusAnnuelFlotte(data);

// ⚠️ SOURCE UNIQUE — dépendances d'un véhicule (factures / amendes / emprunts en cours) avant
// suppression, pour un AVERTISSEMENT identique partout (fiche véhicule ET Contrats).
FP.vehiculeDependances = (v, data) => {
  data = data || {};
  const nk = FP.normImmat((v && v.immat) || '');
  const nbFactures = (data.factures || []).filter(f => FP.normImmat(f.vehiculeImmat) === nk).length;
  const nbAmendes = (data.amendes || []).filter(a => FP.normImmat(a.vehiculeImmat || a.plaque || a.immatriculation) === nk).length;
  let nbEmpOuverts = 0;
  try {
    const EK = 'fp_emprunts_' + ((FP.activeSociete) ? FP.activeSociete() : 'PXP');
    const emps = JSON.parse(localStorage.getItem(EK) || '[]');
    if (Array.isArray(emps)) nbEmpOuverts = emps.filter(e => e && FP.normImmat(e.vehicule) === nk && (FP.empEnCours ? FP.empEnCours(e) : !e.dateRetour)).length;
  } catch (e) {}
  return { nbFactures, nbAmendes, nbEmpOuverts };
};
// Message de confirmation de suppression d'un véhicule — IDENTIQUE partout. Précise ce qui est
// conservé, ce qui reste rattaché, les emprunts ouverts à clôturer, et que la suppression va en
// Corbeille (restaurable) — jamais « irréversible » puisque FP.persist.delete/FP.trash la capture.
FP.vehiculeDeleteMessage = (v, data) => {
  const d = FP.vehiculeDependances(v, data);
  const nom = [v && v.marque, v && v.modele].filter(Boolean).join(' ');
  let msg = `Supprimer le véhicule ${(v && v.immat) || ''}${nom ? ` (${nom})` : ''} ?`;
  if (d.nbFactures > 0) msg += `\n\n⚠️ ${d.nbFactures} facture(s) liées : CONSERVÉES (les dépenses ont eu lieu → elles restent dans l'historique et les totaux de coût).`;
  if (d.nbAmendes > 0) msg += `\n\n⚠️ ${d.nbAmendes} amende(s) resteront rattachées à cette plaque (véhicule disparu).`;
  if (d.nbEmpOuverts > 0) msg += `\n\n⛔ ${d.nbEmpOuverts} emprunt(s) EN COURS (non rendus) : pense à les clôturer d'abord, sinon ils resteront ouverts.`;
  msg += `\n\nLe véhicule part en Corbeille (restaurable). Astuce : pour retirer un véhicule vendu en gardant tout tracé, utilise plutôt le statut « vendu » (ne supprime rien).`;
  return msg;
};
// ⚠️ HELPER CANONIQUE — coût RESTANT À CHARGE d'une facture de sinistre : 0 si remboursé/pris en charge
// (sinistreStatut ∈ {rembourse, pec}) ou si c'est un simple devis (sinistreStage ou mots devis/proforma/
// estimation), sinon le TTC. Même règle que la page Sinistres et le KPI Statistiques.
// Statut de suivi d'un sinistre (— / attente / pec / rembourse / refuse), SOURCE UNIQUE.
// Le statut est saisi PAR INCIDENT (clé de groupe sinistreGroupes[id] || id) dans la page Sinistres,
// mais l'import le pose parfois par id de facture. On résout donc via la clé de groupe D'ABORD,
// puis repli sur l'id de facture → page, alertes et coûts lisent toujours la même valeur.
FP.sinistreStatutOf = (f) => {
  if (!f) return '';
  try {
    const s = FP.settings.get();
    const grp = s.sinistreGroupes || {}, st = s.sinistreStatut || {};
    const gk = grp[f.id] || f.id;
    return (st[gk] || st[f.id] || '').toString().toLowerCase();
  } catch (e) { return ''; }
};
FP.coutSinistre = (f) => {
  try {
    if (!f) return 0;
    const st = FP.sinistreStatutOf(f);
    if (st === 'rembourse' || st === 'pec') return 0;
    const stage = ((FP.settings.get().sinistreStage || {})[f.id] || '').toString().toLowerCase();
    const isDevis = stage ? (stage === 'devis') : /\b(devis|proforma|estimation)\b/i.test(((f.description || '') + ' ' + (f.fournisseur || '')));
    if (isDevis) return 0;
    return Number(f.montantTTC) || 0;
  } catch (e) { return Number(f && f.montantTTC) || 0; }
};
// RESTE À CHARGE réel des sinistres (ce que la société paie vraiment, après remboursement assureur).
// Le remboursement étant saisi PAR INCIDENT (settings.sinistreAssurance[clé].rembourse) et non par
// facture, on REGROUPE d'abord par incident (settings.sinistreGroupes[id] || id), on somme le coût
// (FP.coutSinistre → devis exclus, sinistre 100 % pris en charge = 0), puis on soustrait le remboursé.
// Source unique pour toutes les vues « coût réel » (Coût d'usage, coût/km, TCO).
FP.resteChargeSinistre = function (factures) {
  try {
    const s = FP.settings.get();
    const grp = s.sinistreGroupes || {}, doss = s.sinistreAssurance || {};
    const gk = id => grp[id] || id;
    const byInc = {};
    (factures || []).forEach(f => {
      if (!f || (f.type || '').toLowerCase() !== 'sinistre') return;
      const k = gk(f.id);
      byInc[k] = (byInc[k] || 0) + (FP.coutSinistre ? FP.coutSinistre(f) : (Number(f.montantTTC) || 0));
    });
    let total = 0;
    Object.keys(byInc).forEach(k => { total += Math.max(0, byInc[k] - (Number((doss[k] || {}).rembourse) || 0)); });
    return total;
  } catch (e) { return (factures || []).filter(f => f && (f.type || '').toLowerCase() === 'sinistre').reduce((a, f) => a + (Number(f.montantTTC) || 0), 0); }
};
// ⚠️ HELPER CANONIQUE — dédoublonnage des factures par n° (comme Statistiques / rapport direction) :
// deux lignes qui partagent le même numeroFacture ne sont comptées qu'une fois (évite de gonfler les
// totaux). Les factures sans numéro sont toutes gardées. À utiliser partout où on somme des factures.
FP.dedupeFactures = (list) => {
  const seen = new Set();
  // SOURCE UNIQUE : même normalisation/règle que FP.dupe pour les factures (n° normalisé — accents
  // & ponctuation retirés — de longueur ≥ 4 ET même TTC). Sinon un n° court/séquentiel (« 24 ») ou
  // deux vraies factures au même n° mais montants différents étaient fusionnés à tort (sous-comptage),
  // et une variante de ponctuation (« FA-2026/01 » vs « FA 2026 01 ») n'était PAS fusionnée (sur-comptage).
  const norm = (s) => (FP.dupe && FP.dupe._n) ? FP.dupe._n(s) : (s == null ? '' : String(s)).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
  const numOf = (v) => (FP.dupe && FP.dupe._num) ? FP.dupe._num(v) : (() => { const n = parseFloat(String(v == null ? '' : v).replace(/\s/g, '').replace(',', '.')); return isNaN(n) ? null : n; })();
  return (list || []).filter(f => {
    const k = norm(f && f.numeroFacture);
    if (!k || k.length < 4) return true; // n° absent ou trop court → jamais dédoublonné (peut être une 2e vraie facture)
    const ttc = numOf(f && f.montantTTC);
    const key = k + '|' + (ttc == null ? '' : ttc);
    if (seen.has(key)) return false; seen.add(key); return true;
  });
};
// ⚠️ HELPER CANONIQUE — coût d'exploitation d'un mois : factures dédoublonnées par n° + filtre exploit.
// Même chiffre partout (dashboard, écran mural, rapport direction) — sinon un doublon de n° gonflait le mois.
FP.coutMois = (data, ym) => (FP.dedupeFactures(((data && data.factures) || [])).filter(f => (f.date || '').slice(0, 7) === ym && FP.coutFactureExploit(f)).reduce((s, f) => s + (Number(f.montantTTC) || 0), 0));
// ⚠️ HELPER CANONIQUE — URL ouvrable d'une FACTURE (table `factures`) : fileId = URL http (stockage
// Supabase) OU id Google Drive ; 'IMP-…' ou vide = aucun fichier. SOURCE UNIQUE sur FP (utilisée par
// FP.facturesZip ET FP.docsFolder). ⚠️ Avant, _factUrl n'existait QUE sur FP.docsFolder → FP.facturesZip
// appelait FP._factUrl (inexistant) → url vide → le ZIP ne contenait AUCUN PDF (bug depuis la création
// du bouton). On l'expose donc bien sur FP.
FP._factUrl = function (f) { const id = (f && (f.fileId || f.fileUrl || f.url)) || ''; if (!id || /^IMP-/.test(id)) return ''; if (/^https?:\/\//.test(id)) return id; return 'https://drive.google.com/file/d/' + encodeURIComponent(id) + '/view'; };
// ⚠️ HELPER CANONIQUE — télécharge en UN ZIP toutes les pièces jointes (PDF/scan) des factures d'un
// véhicule + un récapitulatif CSV (« état des factures »). Utilisable sur CHAQUE véhicule (vendu ou non).
//  • Les fichiers hébergés dans Supabase Storage sont RÉCUPÉRÉS et mis dans le ZIP (via URL signée).
//  • Les rares fichiers Google Drive (non téléchargeables côté navigateur / CORS) sont LISTÉS dans
//    liens-Drive.txt → rien n'est perdu, l'utilisateur les récupère depuis Drive. On n'invente rien.
//  • Dédoublonnage par le helper canonique FP.dedupeFactures. Progression via FP.busy ; résumé honnête.
FP.facturesZip = async function (veh) {
  if (!veh || !veh.immat) { if (FP.toast) FP.toast('Véhicule inconnu.'); return; }
  const data = (typeof window !== 'undefined' && window.FP_DATA) || {};
  let list = (data.factures || []).filter(f => f && FP.immatEq(f.vehiculeImmat, veh.immat));
  list = FP.dedupeFactures ? FP.dedupeFactures(list) : list;
  list.sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')));
  if (!list.length) { if (FP.toast) FP.toast('Aucune facture pour ' + (veh.immat || 'ce véhicule') + '.'); else alert('Aucune facture pour ce véhicule.'); return; }
  const busy = FP.busy ? FP.busy('Préparation des factures… 0/' + list.length) : null;
  try {
    if (!window.JSZip && FP.ocr && FP.ocr.loadScript) { try { await FP.ocr.loadScript('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js'); } catch (e) {} }
    if (!window.JSZip) { const m = 'Téléchargement ZIP indisponible (connexion requise).'; if (busy) busy.fail(m); else alert(m); return; }
    const zip = new window.JSZip(), used = {};
    let inc = 0, fail = 0, nofile = 0; const drive = [];
    const rows = [['Date', 'Fournisseur', 'Description', 'N° facture', 'HT', 'TVA', 'TTC', 'Km', 'Fichier']];
    const money = n => (n == null || n === '') ? '' : String(n).replace('.', ',');
    const clean = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^\w .\-]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 70);
    for (let i = 0; i < list.length; i++) {
      const f = list[i];
      if (busy) busy.update('Préparation des factures… ' + (i + 1) + '/' + list.length);
      const url = FP._factUrl ? FP._factUrl(f) : '';
      const isStore = /\/storage\/v1\/object\//.test(url) || /supabase\.co/.test(url);
      const isDrive = /drive\.google\.com/.test(url) || (f.fileId && !/^https?:/i.test(f.fileId) && !/^IMP-/i.test(f.fileId));
      const base = clean((f.date || '').slice(0, 10) + ' ' + (f.fournisseur || 'facture') + (f.montantTTC != null ? ' ' + f.montantTTC + 'EUR' : '')) || ('facture-' + (i + 1));
      let fileCol = '';
      if (url && isStore) {
        try {
          const signed = FP.signedScanUrl ? (await FP.signedScanUrl(url, 600)) : url;
          const resp = await fetch(signed || url); if (!resp.ok) throw new Error('http ' + resp.status);
          const blob = await resp.blob();
          const ext = /pdf/i.test(blob.type) ? '.pdf' : (/jpe?g/i.test(blob.type) ? '.jpg' : (/png/i.test(blob.type) ? '.png' : '.pdf'));
          let fn = base + ext, k = 1; while (used[fn]) { fn = base + ' (' + (++k) + ')' + ext; } used[fn] = 1;
          zip.file(fn, blob); inc++; fileCol = fn;
        } catch (e) { fail++; fileCol = '(échec du téléchargement) ' + url; }
      } else if (url && isDrive) {
        drive.push((f.date || '').slice(0, 10) + ' · ' + (f.fournisseur || '') + (f.montantTTC != null ? ' · ' + f.montantTTC + ' €' : '') + '  →  ' + url);
        fileCol = '(lien Google Drive — voir liens-Drive.txt)';
      } else { nofile++; fileCol = '(aucun fichier joint)'; }
      rows.push([(f.date || '').slice(0, 10), f.fournisseur || '', String(f.description || '').replace(/[\r\n]+/g, ' '), f.numeroFacture || '', money(f.montantHT), money(f.montantTVA), money(f.montantTTC), f.km || '', fileCol]);
    }
    // Récap CSV « état des factures » (séparateur ; + BOM → s'ouvre proprement dans Excel FR).
    const csv = '﻿' + rows.map(r => r.map(c => { const s = String(c == null ? '' : c); return /[;"\n]/.test(s) ? ('"' + s.replace(/"/g, '""') + '"') : s; }).join(';')).join('\r\n');
    zip.file('etat-des-factures.csv', csv);
    if (drive.length) zip.file('liens-Drive.txt', 'Factures hébergées sur Google Drive (à télécharger depuis Drive, non incluses dans le ZIP) :\n\n' + drive.join('\n'));
    const out = await zip.generateAsync({ type: 'blob' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(out);
    a.download = 'Factures-' + (FP.normImmat ? FP.normImmat(veh.immat) : veh.immat) + '.zip';
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => { try { URL.revokeObjectURL(a.href); } catch (e) {} }, 8000);
    const msg = '✓ ' + inc + ' facture(s) dans le ZIP' + (drive.length ? ' · ' + drive.length + ' sur Drive (liens)' : '') + (nofile ? ' · ' + nofile + ' sans fichier' : '') + (fail ? ' · ' + fail + ' échec(s)' : '');
    if (busy) busy.done(msg); else if (FP.toast) FP.toast(msg);
    // ⚠️ HONNÊTETÉ : si des factures sont sur Google Drive, le navigateur NE PEUT PAS les mettre dans le ZIP
    // (sécurité Google). Elles sont alors listées (avec leur lien) dans « liens-Drive.txt » à l'intérieur du
    // ZIP. On le dit CLAIREMENT (sinon l'utilisateur croit que le ZIP est vide « sans raison »).
    if (drive.length) {
      setTimeout(function () {
        try { alert('ℹ️ ' + inc + ' facture(s) incluse(s) dans le ZIP.\n\n' + drive.length + ' facture(s) sont hébergées sur Google Drive : le navigateur ne peut pas les mettre dans le ZIP (sécurité Google). Leurs liens sont dans le fichier « liens-Drive.txt » à l\'intérieur du ZIP, et le détail de toutes les factures est dans « etat-des-factures.csv ».'); } catch (e) {}
      }, 600);
    }
  } catch (e) { const m = 'Erreur lors de la création du ZIP : ' + (e && e.message || e); if (busy) busy.fail(m); else alert(m); }
};
// ⚠️ HELPER CANONIQUE — amende « à payer » (statut tolérant aux accents/espaces/casse) : « à payer »,
// « a payer », « À Payer » … sont tous reconnus, pour que dashboard, page Amendes et alertes comptent pareil.
FP.estAPayer = (a) => { const s = ((a && a.statut) || '').toString().trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); return s === 'a payer'; };
// ⚠️ HELPER CANONIQUE — amende « payée » (symétrique de estAPayer, tolérant accents/casse) : « payée »,
// « payee », « Payé »… tous reconnus. À utiliser partout au lieu de statut === 'payée' (sinon totaux faux).
FP.estPayee = (a) => { const s = ((a && a.statut) || '').toString().trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); return s === 'payee' || s === 'paye'; };
// ⚠️ HELPER CANONIQUE — plaque d'une amende. L'amende NE STOCKE PAS de plaque : elle est liée au
// CONDUCTEUR (prenom). On renvoie donc, dans l'ordre : un champ plaque explicite s'il existe, sinon la
// plaque du véhicule du conducteur — UNIQUEMENT si UN SEUL véhicule (non vendu) correspond (sinon on
// n'invente rien → ''). Sert à afficher la vraie plaque dans les e-mails/rappels d'amende.
FP.amendePlaque = (a) => {
  if (!a) return '';
  const direct = a.immatriculation || a.plaque || a.immat || '';
  if (direct) return direct;
  try {
    const np = FP.normPrenom ? FP.normPrenom(a.prenom) : String(a.prenom || '').trim().toLowerCase();
    if (!np) return '';
    const vs = (window.FP_DATA && Array.isArray(FP_DATA.vehicules) ? FP_DATA.vehicules : [])
      .filter(v => v && v.chauffeur && (FP.normPrenom ? FP.normPrenom(v.chauffeur) === np : String(v.chauffeur).trim().toLowerCase() === np) && !(FP.estVendu && FP.estVendu(v)));
    return vs.length === 1 ? (vs[0].immat || '') : '';
  } catch (e) { return ''; }
};
// ⚠️ HELPER CANONIQUE — « facture d'entretien / réparation » (tolérant à l'accent : entretien, réparation,
// reparation). À utiliser PARTOUT (carnet fiche, page Entretiens, coût véhicule, budget, alertes) — sinon
// une facture typée « reparation » (sans accent) apparaît sur un écran et pas sur l'autre.
FP.estEntretien = (f) => { const t = ((f && f.type) || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim(); return t === 'entretien' || t === 'reparation'; };
// ⚠️ « VRAIE révision » — SOURCE UNIQUE pour la DATE de « dernière révision ». Une révision = entretien
// PÉRIODIQUE / vidange (huile moteur/boîte, révision constructeur, service). PAS un pneu seul, une
// géométrie/parallélisme, une clim, des freins, une suspension… : ce sont des entretiens (type
// 'entretien') mais PAS « la révision ». Bug corrigé : avant, N'IMPORTE quelle facture d'entretien
// (ex. géométrie) faisait sauter la « dernière révision » à sa date. On s'ancre donc sur le LIBELLÉ.
FP.estRevision = (f) => {
  if (!f || !FP.estEntretien(f)) return false;
  const d = (`${(f && f.description) || ''} ${(f && f.type) || ''}`).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  return /revision|vidange|entretien periodique|entretien constructeur|entretien annuel|service constructeur|service entretien|service periodique/.test(d)
      || /huile (moteur|boite|de boite|de transmission)/.test(d);
};
// ⚠️ SOURCE UNIQUE — « cette facture compte-t-elle comme LA révision ? » = FP.estRevision (auto)
// MAIS l'utilisateur a toujours le dernier mot : une correction manuelle (settings.revisionOverride,
// keyée par id de facture : 'oui' force, 'non' exclut) prime sur l'auto-détection. Utilisé PARTOUT où
// on décide de la « dernière révision » (fiche, recompute, import) → plus de mauvaise classification
// silencieuse : quand l'auto se trompe, un clic corrige et c'est mémorisé (même les ré-imports suivent).
FP.compteCommeRevision = (f) => {
  if (!f) return false;
  try {
    const ov = (FP.settings.get().revisionOverride) || {};
    const id = f.id != null ? String(f.id) : null;
    if (id && ov[id] === 'non') return false;
    if (id && ov[id] === 'oui') return true;
  } catch (e) {}
  return FP.estRevision(f);
};
// ⚠️ SOURCE UNIQUE — dernière révision d'un véhicule = { date, facture } de la facture-révision la plus
// récente (au sens de FP.compteCommeRevision). Sert à AFFICHER la date ET la facture source (cliquable)
// dans la fiche, et à recaler v.derniereRevision. Renvoie {date:null, facture:null} si aucune.
FP.derniereRevisionInfo = (v, factures) => {
  try {
    if (!v || !v.immat) return { date: null, facture: null };
    const list = factures || (window.FP_DATA && FP_DATA.factures) || [];
    const nk = FP.normImmat(v.immat);
    const mine = list.filter(f => f && FP.normImmat(f.vehiculeImmat) === nk && FP.compteCommeRevision(f) && f.date)
      .sort((a, b) => String(a.date).localeCompare(String(b.date)));
    const last = mine.length ? mine[mine.length - 1] : null;
    return { date: last ? last.date : null, facture: last };
  } catch (e) { return { date: null, facture: null }; }
};
// ⚠️ SOURCE UNIQUE — « DERNIÈRE RÉVISION » affichée PARTOUT (en-tête fiche, panneau « Entretien &
// échéances », colonne du tableau, exports). Prend la date la PLUS RÉCENTE entre : (1) la révision
// détectée sur facture (FP.derniereRevisionInfo, avec la correction « Pas une révision ») et (2) la date
// STOCKÉE/SAISIE À LA MAIN (v.derniereRevision). Corrige le bug « deux dates différentes sur la même
// fiche » : avant, l'en-tête lisait la facture et le panneau lisait le champ stocké → ils divergeaient.
// Renvoie { date, facture, km } — `facture` n'est fourni que si la date retenue vient BIEN de cette
// facture ; `km` = km « à la révision » (celui de la facture de révision retenue si dispo, sinon le
// km relevé du véhicule `kmDernierReleve`), null si aucun. SOURCE UNIQUE du km de révision (tuile
// en-tête + panneau Entretien + export), au même titre que la date.
FP.derniereRevision = (v, factures) => {
  try {
    if (!v) return { date: null, facture: null, km: null };
    const info = FP.derniereRevisionInfo(v, factures);
    // ⚠️ Ignore une date à l'année ABERRANTE (hors 1990–2100, ex. « 0002-07-09 » saisie par erreur) → traitée
    //    comme « pas de date » : évite l'affichage « en retard 738969 j ». La donnée stockée n'est PAS modifiée
    //    (l'utilisateur la ressaisit dans la fiche) — c'est juste l'affichage/calcul qui l'écarte.
    const _okDate = (s) => { const m = /^(\d{4})-\d{2}-\d{2}$/.exec(s || ''); return !!(m && +m[1] >= 1990 && +m[1] <= 2100); };
    const _fdate = info.date ? String(info.date).slice(0, 10) : null;
    const fdate = _okDate(_fdate) ? _fdate : null;
    const _stored = (v.derniereRevision && v.derniereRevision !== '—') ? String(v.derniereRevision).slice(0, 10) : null;
    const stored = _okDate(_stored) ? _stored : null;
    let date = null;
    if (stored && fdate) date = (stored >= fdate) ? stored : fdate;   // la plus récente des deux
    else date = stored || fdate;
    const fac = (fdate && date === fdate) ? info.facture : null;
    const facKm = (fac && Number(fac.km) > 0) ? Number(fac.km) : null;
    const km = (facKm != null) ? facKm : ((Number(v.kmDernierReleve) > 0) ? Number(v.kmDernierReleve) : null);
    return { date: date || null, facture: fac, km };
  } catch (e) { return { date: null, facture: null, km: null }; }
};
// Corrige manuellement le statut « révision » d'une facture, persiste le choix (multi-appareils) et
// recale la « dernière révision » du véhicule (source unique = FP.recomputeVehiculeFromFactures).
// val : 'oui' (forcer révision) | 'non' (exclure) | 'auto' (revenir à l'auto-détection).
FP.setRevisionOverride = function (factureId, val, veh, factures) {
  try {
    const s = FP.settings.get();
    s.revisionOverride = (s.revisionOverride && typeof s.revisionOverride === 'object') ? s.revisionOverride : {};
    const id = String(factureId);
    if (val === 'oui' || val === 'non') s.revisionOverride[id] = val; else delete s.revisionOverride[id];
    FP.settings.save(s);
    if (veh && FP.recomputeVehiculeFromFactures) FP.recomputeVehiculeFromFactures(veh, factures || (window.FP_DATA && FP_DATA.factures) || []);
  } catch (e) {}
  return FP.derniereRevisionInfo(veh, factures);
};
// ⚠️ REPASSE SÛRE (une fois) — corrige les « dernière révision » posées à TORT par l'ancienne règle
// (n'importe quel entretien — géométrie, pneu, clim… — faisait sauter la date). RÈGLES DE SÉCURITÉ
// (rule 0-perte / ⑤) : ne corrige QUE si la date stockée correspond EXACTEMENT à la date d'une facture
// d'entretien du véhicule (= elle vient BIEN d'une facture, pas d'une saisie manuelle) ET qu'elle diffère
// de la vraie dernière révision recalculée. Une date SAISIE À LA MAIN (qui ne correspond à aucune
// facture) n'est JAMAIS touchée. Idempotent (re-passe = aucun changement). Ne touche ni le km ni les pneus.
FP.auditRevisions = function (opts) {
  opts = opts || {};
  const apply = opts.apply !== false;
  const factures = opts.factures || (window.FP_DATA && FP_DATA.factures) || [];
  const vehicules = opts.vehicules || (window.FP_DATA && FP_DATA.vehicules) || [];
  const corrections = [];
  try {
    vehicules.forEach(v => {
      if (!v || !v.immat) return;
      const cur = v.derniereRevision;
      if (!cur || cur === '—') return;                       // rien de stocké → on n'invente rien
      const nk = FP.normImmat(v.immat);
      const mine = factures.filter(f => f && FP.estEntretien(f) && FP.normImmat(f.vehiculeImmat) === nk);
      const vientDuneFacture = mine.some(f => f.date === cur); // la date stockée = une facture d'entretien ?
      if (!vientDuneFacture) return;                          // sinon = saisie MANUELLE → on ne touche JAMAIS
      const info = FP.derniereRevisionInfo(v, factures);      // vraie dernière révision (nouvelle règle + overrides)
      const neuf = info.date || null;
      if ((neuf || null) === (cur || null)) return;          // déjà correct
      corrections.push({ id: v.id, immat: v.immat, ancienne: cur, nouvelle: neuf });
      if (apply) {
        v.derniereRevision = neuf;
        if (FP.persist && FP.persist.update) { try { FP.persist.update('vehicules', v.id, { derniereRevision: neuf }); } catch (e) {} }
      }
    });
  } catch (e) {}
  return corrections;
};
// Repasse UNE FOIS après chargement des données (fp:data-ready), une fois par société (flag persistant).
// Idempotente et sans risque de perte → même relancée, elle ne casse rien.
FP._fixRevisionsUneFois = function () {
  try {
    const s = FP.settings.get();
    if (s.revisionFix1) return;                              // déjà fait → on ne repasse plus
    const done = FP.auditRevisions({ apply: true });
    s.revisionFix1 = true; FP.settings.save(s);
    if (done.length && FP.toast) FP.toast(done.length + ' fiche' + (done.length > 1 ? 's' : '') + ' — dernière révision recalculée');
    if (done.length) { try { console.warn('[révisions] corrigées :', done.map(c => c.immat + ' ' + c.ancienne + '→' + (c.nouvelle || '∅')).join(', ')); } catch (e) {} }
  } catch (e) {}
};
try { document.addEventListener('fp:data-ready', () => { setTimeout(() => { try { FP._fixRevisionsUneFois(); } catch (e) {} }, 1200); }); } catch (e) {}
// ⚠️ SOURCE UNIQUE — « Dépensé {année} » d'un véhicule = entretien/réparation (factures DÉDOUBLONNÉES)
// + sinistres à charge (FP.coutSinistre). Utilisé par la fiche véhicule À L'ÉCRAN et dans son PDF pour
// afficher EXACTEMENT le même montant (sinon le PDF sur-comptait les doublons et ignorait les sinistres).
FP.coutExploitAnnee = (v, annee, factures) => {
  try {
    if (!v) return 0;
    const list = factures || (window.FP_DATA && FP_DATA.factures) || [];
    const an = String(annee);
    const mine = FP.dedupeFactures(list.filter(f => FP.normImmat(f.vehiculeImmat) === FP.normImmat(v.immat)));
    let tot = 0;
    mine.forEach(f => {
      if (!String(f.date || '').startsWith(an)) return;
      const t = String(f.type || '').toLowerCase();
      // Sinistre = seulement le reste à charge (franchise), jamais le montant brut de réparation.
      if (t === 'sinistre') { tot += (FP.coutSinistre ? FP.coutSinistre(f) : 0); return; }
      // Tout le reste de l'EXPLOITATION (entretien, réparation, CARBURANT, PÉAGES, autres frais) au TTC,
      // via le MÊME périmètre que le dashboard/budget/TCO (FP.coutFactureExploit = hors leasing/achat/cession).
      // Avant, « Dépensé {année} » ne comptait QUE l'entretien → il mentait vs le coût au km et le TCO.
      else if (FP.coutFactureExploit(f)) tot += Number(f.montantTTC) || 0;
    });
    return tot;
  } catch (e) { return 0; }
};
// ⚠️ HELPER CANONIQUE — kilométrage RÉEL d'un véhicule : le max entre le km à jour et le km de la dernière
// révision (le véhicule ne peut pas rouler moins que son dernier relevé). À utiliser partout où on AFFICHE
// « km actuel », pour que même des données non réconciliées (data.js figé) montrent la bonne valeur.
FP.kmActuel = (v) => Math.max(Number(v && v.km) || 0, Number(v && v.kmDernierReleve) || 0);
// ⚠️ ÉCRIVAIN CANONIQUE DU KILOMÉTRAGE — source UNIQUE (règle « une règle = une implémentation »).
// La garde « le km ne peut que MONTER » se compare TOUJOURS à FP.kmActuel(v) (= max(km, kmDernierReleve)),
// JAMAIS à v.km brut (sinon un relevé plus récent est écrasé → bug vécu : EDL/remise qui baissent le km).
// opts.force = correction MANUELLE assumée (gestionnaire) : autorise la baisse ET recale kmDernierReleve.
// Persiste (override local + Supabase) et renvoie true si le km a changé. À utiliser PARTOUT où l'on écrit un km.
FP.setVehKm = function (v, newKm, opts) {
  try {
    opts = opts || {};
    if (!v || v.id == null) return false;
    const n = parseInt(String(newKm == null ? '' : newKm).replace(/[^\d]/g, ''), 10);
    if (!Number.isFinite(n) || n < 0) return false;
    const cur = FP.kmActuel(v);
    if (!opts.force && !(n > cur)) return false;   // ne monte pas → on ne touche à rien
    const patch = { km: n };
    v.km = n;
    // Correction forcée VERS LE BAS : il faut aussi redescendre kmDernierReleve, sinon FP.kmActuel garde l'ancien max.
    if (opts.force && (Number(v.kmDernierReleve) || 0) > n) { v.kmDernierReleve = n; patch.kmDernierReleve = n; }
    if (FP.saveVehicleOverride) FP.saveVehicleOverride(v.id, patch);
    if (FP.db && FP.db.update && FP.supabase) {
      FP.db.update('vehicules', v.id, patch)
        .then((res) => { if (res && res.error) { if (FP.notifyError) FP.notifyError('Km : échec serveur — réessaie.'); return; } if (FP.removeVehicleOverride) Object.keys(patch).forEach(k => FP.removeVehicleOverride(v.id, k)); if (FP.refreshDataCache) FP.refreshDataCache(); })
        .catch(() => { if (FP.notifyError) FP.notifyError('Km : échec serveur — réessaie.'); });
    }
    return true;
  } catch (e) { return false; }
};
// ⚠️ HELPER CANONIQUE — STATUT D'ÉCHÉANCE (libellé + couleur) UNIFIÉ pour CT, permis, assurance, entretien.
// Le décompte en jours vient de FP.joursRestants (minuit→minuit) ; les SEUILS bientôt/urgent sont
// CENTRALISÉS ici → tous les écrans colorent pareil (avant : CT 30/60 ici, 90 là ; permis 183 vs 60…).
FP.ECHEANCE_SEUILS = {
  ct:        { urgent: 30, bientot: 60 },   // contrôle technique
  permis:    { urgent: 30, bientot: 90 },   // permis de conduire (3 mois pour anticiper le renouvellement)
  assurance: { urgent: 15, bientot: 45 },
  entretien: { urgent: 15, bientot: 45 },
  defaut:    { urgent: 15, bientot: 60 }
};
FP.ECHEANCE_COULEUR = { expire: '#DC2626', urgent: '#EA580C', bientot: '#D97706', valide: '#16A34A', inconnu: '#94A3B8' };
// Renvoie { jours, statut: 'expire'|'urgent'|'bientot'|'valide'|'inconnu', couleur }. `kind` ∈ clés ci-dessus.
FP.echeanceStatut = function (dateOrISO, kind) {
  const j = FP.joursRestants ? FP.joursRestants(dateOrISO) : null;
  if (j == null) return { jours: null, statut: 'inconnu', couleur: FP.ECHEANCE_COULEUR.inconnu };
  // CT : les seuils suivent le RÉGLAGE configurable `notifCfg().ctJours` (Paramètres → Notifications),
  // comme les alertes et Entretiens (urgent = ctJours/3, bientôt = ctJours×2/3 → 30/60 par défaut à 90).
  // → une SEULE vérité pour la couleur/urgence du CT : tableau Véhicules, fiche, Contrats, Alertes.
  let S;
  if (kind === 'ct' && FP.notifCfg) { const I = (FP.notifCfg().ctJours || 90); S = { urgent: Math.round(I / 3), bientot: Math.round(I * 2 / 3) }; }
  // PERMIS + PIÈCE D'IDENTITÉ : seuils = réglage configurable `notifCfg().docAlerteJours` (bientôt = X j,
  // urgent = X/2), EXACTEMENT comme les Alertes et Renouvellements. Avant : seuils figés 30/90 ici → la
  // fiche conducteur affichait « valide » quand les Alertes affichaient déjà « à renouveler ». Une seule vérité.
  else if ((kind === 'permis' || kind === 'piece' || kind === 'pièce') && FP.notifCfg) { const W = (FP.notifCfg().docAlerteJours || 120); S = { urgent: Math.round(W / 2), bientot: W }; }
  else S = FP.ECHEANCE_SEUILS[kind] || FP.ECHEANCE_SEUILS.defaut;
  let statut = 'valide';
  if (j < 0) statut = 'expire'; else if (j <= S.urgent) statut = 'urgent'; else if (j <= S.bientot) statut = 'bientot';
  return { jours: j, statut, couleur: FP.ECHEANCE_COULEUR[statut] };
};
// ⚠️ HELPER CANONIQUE — KM ANNUEL RÉEL (estimé) d'un véhicule, pour le bilan CO₂ (et tout calcul « /an »).
// Bien plus juste que le forfait 15 000 km : on prend le VRAI rythme du véhicule, dans cet ordre :
//   1) RELEVÉS KM (source unique FP.kmCollecte) : ≥2 relevés espacés d'au moins 30 j → (Δkm ÷ Δjours)×365.
//   2) MOYENNE À VIE : km au compteur ÷ ancienneté (depuis la 1re mise en circulation).
//   3) REPLI : 15 000 km/an (moyenne conventionnelle) si aucune donnée exploitable.
// Bornes de sécurité 500–80 000 km/an pour écarter les valeurs aberrantes (saisie/OCR douteux).
FP.KM_AN_DEFAUT = 15000;
FP.kmAnnuel = function (v) {
  if (!v) return FP.KM_AN_DEFAUT;
  const _ok = (x) => (isFinite(x) && x >= 500 && x <= 80000) ? Math.round(x) : null;
  try {
    // 1) Rythme réel via les relevés km
    const KC = FP.kmCollecte;
    if (KC && KC.recusDe) {
      const reads = (KC.recusDe(v) || [])
        .filter(r => r && r.used_at && r.km_recu != null)
        .map(r => ({ t: new Date(r.used_at).getTime(), km: Number(r.km_recu) }))
        .filter(r => isFinite(r.t) && isFinite(r.km))
        .sort((a, b) => a.t - b.t);
      if (reads.length >= 2) {
        const first = reads[0], last = reads[reads.length - 1];
        const dDays = (last.t - first.t) / 86400000, dKm = last.km - first.km;
        if (dDays >= 30 && dKm > 0) { const r = _ok(dKm / dDays * 365); if (r) return r; }
      }
    }
  } catch (e) {}
  try {
    // 2) Moyenne « à vie » : compteur ÷ ancienneté
    const km = FP.kmActuel ? FP.kmActuel(v) : (Number(v.km) || 0);
    const dmc = v.dateMiseEnCirculation ? new Date(v.dateMiseEnCirculation) : null;
    if (km > 0 && dmc && !isNaN(dmc)) {
      const ageAns = (Date.now() - dmc.getTime()) / (365.25 * 86400000);
      if (ageAns >= 0.5) { const r = _ok(km / ageAns); if (r) return r; }
    }
  } catch (e) {}
  return FP.KM_AN_DEFAUT;   // 3) repli conventionnel
};
// Comment le km/an a été obtenu (pour l'afficher / l'expliquer) : 'releves' | 'anciennete' | 'defaut'.
FP.kmAnnuelSource = function (v) {
  try {
    const KC = FP.kmCollecte;
    if (KC && KC.recusDe) {
      const reads = (KC.recusDe(v) || []).filter(r => r && r.used_at && r.km_recu != null)
        .map(r => ({ t: new Date(r.used_at).getTime(), km: Number(r.km_recu) })).filter(r => isFinite(r.t) && isFinite(r.km)).sort((a, b) => a.t - b.t);
      if (reads.length >= 2) { const f = reads[0], l = reads[reads.length - 1]; const dD = (l.t - f.t) / 86400000, dK = l.km - f.km; if (dD >= 30 && dK > 0) { const an = dK / dD * 365; if (an >= 500 && an <= 80000) return 'releves'; } }
    }
    const km = FP.kmActuel ? FP.kmActuel(v) : (Number(v.km) || 0);
    const dmc = v.dateMiseEnCirculation ? new Date(v.dateMiseEnCirculation) : null;
    if (km > 0 && dmc && !isNaN(dmc)) { const a = (Date.now() - dmc.getTime()) / (365.25 * 86400000); if (a >= 0.5) { const an = km / a; if (an >= 500 && an <= 80000) return 'anciennete'; } }
  } catch (e) {}
  return 'defaut';
};
// ⚠️ HELPERS CANONIQUES — statut d'un emprunt. « en cours » = pas encore rendu (dateRetour absente ou
// sentinelle inconnue). À utiliser partout (page Emprunts, dashboard, fiche véhicule) — sinon deux écrans
// divergent sur « ce véhicule est-il sorti ? ».
FP.EMP_RETOUR_INCONNU = '1900-01-01';
// ⚠️ Sémantique alignée sur l'UI : une dateRetour renseignée = RENDU (y compris la sentinelle
// « 1900-01-01 » = rendu à une date inconnue, via la case « je ne connais pas la date de retour »).
// EN COURS = aucune dateRetour du tout. (Ne PAS traiter la sentinelle comme « en cours ».)
FP.empEnCours = (e) => !(e && e.dateRetour && String(e.dateRetour).slice(0, 10));
// Jours écoulés depuis la date d'emprunt (calendaires, minuit → aujourd'hui).
FP.empJoursDepuis = (e) => { const d = (e && e.dateEmprunt) ? new Date(String(e.dateEmprunt).slice(0, 10)) : null; if (!d || isNaN(d)) return 0; const t = new Date(); t.setHours(0, 0, 0, 0); return Math.floor((t - d) / 86400000); };
// SOURCE UNIQUE « emprunt en retard » (règle choisie par l'utilisateur) : en cours ET emprunté
// depuis plus de X jours (réglable dans Paramètres → Seuils d'alerte, défaut 2). Utilisé par le
// tableau de bord ET la page Emprunts.
FP.empRetardJours = () => { try { return FP.notifCfg ? FP.notifCfg().empruntRetardJours : 2; } catch (e) { return 2; } };
FP.empEnRetard = (e) => FP.empEnCours(e) && FP.empJoursDepuis(e) > FP.empRetardJours();
// ⚠️ SOURCE UNIQUE — recalcule la fiche véhicule à partir des factures RESTANTES (à appeler après la
// SUPPRESSION d'une facture, symétrique de FP.applyFactureToVehicule). Évite les « dernière révision /
// km / pneus » fantômes laissés par une facture supprimée. Ne fait jamais BAISSER le km affiché (v.km),
// mais recale la dernière révision, le km de révision et la date pneus sur ce qui reste réellement.
FP.recomputeVehiculeFromFactures = function (v, factures) {
  try {
    if (!v || !v.immat) return null;
    const nk = FP.normImmat(v.immat);
    const mine = (factures || []).filter(f => f && FP.estEntretien(f) && FP.normImmat(f.vehiculeImmat) === nk);
    // ⚠️ SYMÉTRIE avec FP.applyFactureToVehicule : le km relevé s'applique depuis N'IMPORTE QUELLE
    // facture (pas seulement l'entretien). On recalcule donc kmDernierReleve sur TOUTES les factures
    // restantes du véhicule — sinon supprimer/éditer une facture d'entretien ferait RÉGRESSER le km
    // relevé alors qu'une facture non-entretien (carburant, péage…) porte un km plus élevé → échéance
    // de révision (FP.revisionInfo, ancrée sur kmDernierReleve) faussée.
    const allMine = (factures || []).filter(f => f && FP.normImmat(f.vehiculeImmat) === nk);
    const patch = {};
    // Dernière révision = date la plus récente parmi les VRAIES révisions restantes (FP.compteCommeRevision :
    // auto-détection + corrections manuelles ; une géométrie/pneu/clim ne compte PAS comme révision).
    const dates = mine.filter(f => FP.compteCommeRevision(f)).map(f => f.date).filter(Boolean).sort();
    const derniere = dates.length ? dates[dates.length - 1] : null;
    if ((v.derniereRevision || null) !== (derniere || null)) { v.derniereRevision = derniere; patch.derniereRevision = derniere; }
    // Km relevé = max km parmi TOUTES les factures restantes (même périmètre qu'apply), sinon vide.
    const kms = allMine.map(f => Number(f.km)).filter(n => Number.isFinite(n) && n > 0);
    const kmRev = kms.length ? Math.max(...kms) : null;
    if ((Number(v.kmDernierReleve) || null) !== (kmRev || null)) { v.kmDernierReleve = kmRev; patch.kmDernierReleve = kmRev; }
    // Date pneus = date la plus récente parmi les factures d'entretien « pneu » restantes (sinon vide).
    const pneuDates = mine.filter(f => /pneu/i.test(String(f.description || ''))).map(f => f.date).filter(Boolean).sort();
    const pneu = pneuDates.length ? pneuDates[pneuDates.length - 1] : null;
    if ((v.dateChangementPneus || null) !== (pneu || null)) { v.dateChangementPneus = pneu; patch.dateChangementPneus = pneu; }
    if (!Object.keys(patch).length) return null;
    if (FP.persist && FP.persist.update) { try { FP.persist.update('vehicules', v.id, patch); } catch (e) {} }
    return { veh: v, patch };
  } catch (e) { return null; }
};
// ⚠️ HELPER CANONIQUE — nom du loueur d'un véhicule (multi-loueurs) : on matche le propriétaire du
// véhicule sur settings.loueurs[].prop ; repli sur le propriétaire brut puis sur le loueur unique du
// profil (loueurNom). Sert au LIBELLÉ « Forfait leasing X » de la fiche (sans toucher à la détection
// du leasing) — sinon une société multi-loueurs affichait toujours le loueur unique du profil.
FP.loueurOf = (v) => {
  const p = String((v && v.proprietaire) || '').trim(); const pl = p.toLowerCase();
  let list = []; try { const s = FP.settings.get(); if (Array.isArray(s.loueurs)) list = s.loueurs; } catch (e) {}
  const m = pl ? (list || []).find(l => l && String(l.prop || '').trim().toLowerCase() === pl) : null;
  if (m && m.nom) return String(m.nom).trim();
  const prof = FP.societeProfil ? FP.societeProfil() : {};
  // Loueur du profil (ex. PXP → propriétaire « BPCE », loueurNom « BPCE Car Lease ») : si le
  // propriétaire du véhicule correspond à l'étiquette propriétaire du profil, on renvoie le NOM
  // COMPLET du loueur — MÊME libellé que la liste Contrats (avant : la fiche/l'export montraient
  // « BPCE » et l'écran « BPCE Car Lease »). Inerte hors PXP (propProfil vide → pas de fuite).
  const propProfil = String(prof.proprietaireLeasing || prof.loueurNom || '').trim().toLowerCase();
  if (pl && propProfil && pl === propProfil && prof.loueurNom) return String(prof.loueurNom).trim();
  if (p) return p;
  return String(prof.loueurNom || '').trim();
};

// Masses en ORDRE DE MARCHE (champ G de la carte grise, en kg) — c'est le champ qu'utilise
