// Remplissage GÉNÉRIQUE des balises d'un modèle e-mail ({prenom} = 1er mot ; {plaque}/{immat}/{motif}/
// {date}/{email}). Une balise vide disparaît proprement (avec son espace). Source unique côté site + repli.
FP.fillTags = function (tpl, o) {
  o = o || {};
  let s = String(tpl == null ? '' : tpl);
  const first = String(o.prenom || '').trim().split(/\s+/)[0] || '';
  const _avis = (o.avis != null ? o.avis : o.numeroAvis);
  const map = { prenom: first, plaque: o.plaque, immat: o.immat, motif: o.motif, date: o.date, email: o.email, modele: o.modele, avis: _avis, numeroAvis: _avis };
  Object.keys(map).forEach(k => {
    const v = String(map[k] == null ? '' : map[k]).trim();
    s = s.replace(new RegExp('\\{' + k + '\\}', 'gi'), v);   // remplacement DIRECT (pas d'espace ajouté)
  });
  // Nettoyage : parenthèses vides, doubles espaces, espace avant . , ) ] (PAS avant : ; ! ? — le
  // français garde l'espace), espaces/ lignes en trop.
  return s.replace(/\(\s*\)/g, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/ +([)\].,])/g, '$1')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};
// ⚠️ MODÈLES PÉRIMÉS à IGNORER (auto-upgrade propre, SANS réécrire les réglages) : un texte enregistré qui est
// en fait un ANCIEN défaut (formulation « échéance le {date} » qui devient moche avec la nouvelle balise) est
// traité comme « non personnalisé » → on retombe sur le NOUVEAU défaut. L'utilisateur garde son vrai texte s'il
// l'a VRAIMENT personnalisé. Comparaison exacte (trim) : on ne touche que les anciens défauts connus.
FP._MAIL_OBSOLETE = {
  relanceEntretien: [
    'Bonjour {prenom},\n🛠️ Le véhicule {immat} a un entretien à prévoir (échéance le {date}) 🚗 — pense à caler un passage au garage.',
    'Bonjour {prenom},\n🛠️ Le véhicule {immat} : révision {date} 🚗 — pense à caler un passage au garage.'
  ],
  relanceEntretien_en: [
    'Hello {prenom},\n🛠️ Vehicle {immat} has maintenance due ({date}) 🚗 — remember to book a garage visit.',
    'Hello {prenom},\n🛠️ Vehicle {immat}: service {date} 🚗 — remember to book a garage visit.'
  ]
};
FP._mailEstObsolete = function (defKey, val) { const a = (FP._MAIL_OBSOLETE && FP._MAIL_OBSOLETE[defKey]) || []; const t = String(val == null ? '' : val).trim(); return a.some(s => String(s).trim() === t); };
// Modèle e-mail ACTIF : texte personnalisé de la société (profil[profilKey]) sinon défaut (MAIL_DEFAUT[defKey]).
FP.mailModeleProfil = function (profilKey, defKey) { return FP.mailModeleProfilL(profilKey, defKey, 'fr'); };
// Idem, mais SELON LA LANGUE (fr/en). lang==='en' → modèle EN personnalisé (profil[key+'_en']) sinon
// défaut EN (MAIL_DEFAUT[def+'_en']) ; à défaut, repli sur le FR (édité sinon défaut). ⚠️ SOURCE UNIQUE :
// tout e-mail passe par ici → éditer le champ EN dans Paramètres change bien le mail envoyé (jamais en dur).
FP.mailModeleProfilL = function (profilKey, defKey, lang) {
  let prof = {}; try { prof = FP.societeProfil ? FP.societeProfil() : {}; } catch (e) {}
  const en = String(lang) === 'en';
  // ⚠️ PRIORITÉ : le texte CONFIGURÉ par l'utilisateur passe AVANT le défaut « en dur ». Ordre :
  //   1) EN personnalisé (si conducteur EN)  2) FR personnalisé (les « réglages » de l'utilisateur)
  //   3) défaut EN  4) défaut FR. Sinon un conducteur marqué EN recevait le DÉFAUT anglais au lieu du
  //   modèle FR saisi par l'utilisateur → « j'ai pas les mêmes mails que dans mes réglages ». Un vrai
  //   texte anglais s'obtient en remplissant le champ « English » du modèle (il repasse alors en tête).
  if (en) { const ve = prof[profilKey + '_en']; if (ve && String(ve).trim() && !FP._mailEstObsolete(defKey + '_en', ve)) return String(ve); }
  const v = prof[profilKey]; if (v && String(v).trim() && !FP._mailEstObsolete(defKey, v)) return String(v);   // FR personnalisé = les réglages de l'utilisateur (sauf ancien défaut périmé → nouveau défaut)
  if (en) { const de = FP.MAIL_DEFAUT[defKey + '_en']; if (de && String(de).trim()) return String(de); }
  return FP.MAIL_DEFAUT[defKey] || '';
};
// ===== OBJET (titre) de chaque e-mail — ÉDITABLE dans Paramètres → E-mails =====
// Défauts par type d'e-mail. Balises {…} remplies par FP.fillTags ({prenom}{plaque}{immat}{motif}
// {date}{email}{avis}{modele}). ⚠️ AMENDE : les 3 e-mails (paiement/désignation/relance) PARTAGENT
// le même objet « CONTRAVENTION {avis} » → ils restent groupés dans la boîte du destinataire
// (le fil est de toute façon garanti par les en-têtes References/In-Reply-To, l'objet peut donc
// changer sans casser le regroupement).
FP.MAIL_OBJET_DEFAUT = {
  amende: 'CONTRAVENTION {avis}',
  amende_en: 'FINE {avis}',
  signature: "Signature de l'état des lieux — {immat}",
  bienvenue: "Bienvenue à bord 🚗 — ton espace véhicule",
  relevekm: 'Relevé kilométrique — {immat}',
  rdvgarage: '{motif} le {date} ({immat})',
  rappelgarage: 'Rappel : {motif} demain ({immat})',
  invitation: 'Bienvenue sur Parc Pilot 🎉 — ton accès',
  relanceCt: 'Contrôle technique — {immat}',
  relanceEntretien: 'Entretien à prévoir — {immat}',
  relanceGarage: 'Rendez-vous garage — {immat}',
  relanceKm: 'Relevé kilométrique — {immat}',
  relanceAmende: 'Amende à régler — {immat}',
  // Objets ANGLAIS (éditables — section « English e-mails »).
  signature_en: 'Condition report to sign — {immat}',
  bienvenue_en: 'Welcome on board 🚗 — your vehicle space',
  relevekm_en: 'Mileage reading — {immat}',
  rdvgarage_en: '{motif} on {date} ({immat})',
  rappelgarage_en: 'Reminder: {motif} tomorrow ({immat})',
  invitation_en: 'Welcome to Parc Pilot 🎉 — your access',
  relanceCt_en: 'Roadworthiness test — {immat}',
  relanceEntretien_en: 'Maintenance due — {immat}',
  relanceGarage_en: 'Garage appointment — {immat}',
  relanceKm_en: 'Mileage reading — {immat}',
  relanceAmende_en: 'Fine to settle — {immat}',
};
// Objet e-mail ACTIF (personnalisé société sinon défaut), balises déjà remplies. `defKey` = clé de
// MAIL_OBJET_DEFAUT ; le champ profil correspondant est `mailObjet<DefKey>` (1re lettre en maj).
FP.mailObjet = function (defKey, tags) { return FP.mailObjetL(defKey, tags, 'fr'); };
// Objet e-mail ACTIF selon la langue (fr/en). En anglais : profil[mailObjet<Def>_en] sinon défaut EN,
// sinon repli FR. `defKey` NE DOIT PAS déjà contenir « _en » (le suffixe est ajouté ici).
FP.mailObjetL = function (defKey, tags, lang) {
  let prof = {}; try { prof = FP.societeProfil ? FP.societeProfil() : {}; } catch (e) {}
  const Cap = String(defKey).charAt(0).toUpperCase() + String(defKey).slice(1);
  const en = String(lang) === 'en';
  let raw = '';
  // Même priorité que le CORPS : objet EN perso → objet FR perso (les réglages) → défaut EN → défaut FR.
  if (en) { const pe = prof['mailObjet' + Cap + '_en']; if (pe && String(pe).trim()) raw = String(pe); }
  if (!raw) { const p = prof['mailObjet' + Cap]; if (p && String(p).trim()) raw = String(p); }
  if (!raw && en && FP.MAIL_OBJET_DEFAUT[defKey + '_en']) raw = FP.MAIL_OBJET_DEFAUT[defKey + '_en'];
  if (!raw) raw = FP.MAIL_OBJET_DEFAUT[defKey] || '';
  const out = FP.fillTags ? FP.fillTags(raw, tags || {}) : raw;
  return String(out || '').trim();
};
